programs.sol:
"""A partial speech/transcript-cue approximation, not a general text classifier.

Positive responses mark conversational phrases, public-speaking titles and
turn punctuation, escaped line wrapping, and subtitle clock separators.
Recent fillers and speaker labels strengthen conversational responses; escaped
newlines plus titles strengthen formal-transcript responses. Other tokens are
usually zero; alphabetic document starts get a small negative bias. Keep only
400 characters of history, resetting between documents.
"""
import re

READS = ()
PUBLIC_ROLES = {
    'House', 'Chairman', 'Chair', 'Senator', 'Minister', 'Secretary',
    'President', 'Government', 'gentleman', 'witness', 'Members',
}
COURTESY_TITLES = {'Mr', 'Ms', 'Mrs', 'Dr', 'Hon'}
OPENERS = {'And': (4.21, 1.78), 'So': (3.97, 1.39), 'Well': (0., 2.74)}
ROLE = re.compile(r'\b(?:Mr|Mrs|Ms|Dr|Chairman|Senator|Secretary|President)\b')
LABEL = re.compile(r'(?:^|\n|\\n)\s*(?:(?:Mr|Mrs|Ms|Dr)\.\s*)?'
                   r'(?:[A-Z][\w\'-]*[ .]*){1,4}$')
FILLERS = re.compile(
    r'\b(?:you know|I mean|kind of|sort of|gonna|And so|And then|'
    r'So I|So we|I think|I just|thank you|'
    r'(?:I|you|we|they)[’\'](?:m|re|ve|ll))\b', re.I)
TURNS = re.compile(
    r'(?:^|\n|\\n)(?:[A-Z][a-z]+(?: [A-Z][a-z]+){0,2}|[A-Z]{2,20}):')
TURN_TITLE = re.compile(
    r'(?:(?:Mr|Mrs|Ms|Dr)\. |(?:The )?(?:Chairman|Senator|Secretary) )')
CUES = PUBLIC_ROLES | COURTESY_TITLES | set(OPENERS) | {
    'just', 'know', 'think', 'of', 'right', 'then', 'like', 'Thank',
    'today', 'tonight', '.', '.\\', ':', ',', '\\', '--', '----',
    '…', '.…', "'re", '’re',
}


def predict(before, token):
    word = token.strip()
    value = -0.27 if not before and any(c.isalpha() for c in word) else 0.
    if word not in CUES and token != '   ':
        return value

    recent = before[-320:]
    plain = before.replace('\\n', '\n')
    hearing = float('\\n' in recent and
                    bool(ROLE.search(recent.replace('\\n', '\n'))))
    speech = max(min(3, len(FILLERS.findall(recent.replace('\\n', '\n')))) / 3.,
                 min(1., len(TURNS.findall(recent)) / 2.))
    previous = re.search(r"([A-Za-z]+|[’'][A-Za-z]+)\s*$", plain)
    previous = previous.group(1) if previous else ''
    lower = previous.lower()

    # Printed turn layout and line wrapping in formal transcripts.
    if token == '   ' and before.endswith(('\\n', '\n')):
        value += 5.22 * hearing
    if word == '\\' and token.startswith(' ') and previous:
        value += 0.45 + 1.45 * hearing + 1.43 * speech
    if word in {'--', '----', '…', '.…'}:
        value += 3.57 * hearing

    if word in {'.', '.\\'}:
        if lower == 'mr':
            value += 1.21 + 4.24 * hearing
        elif lower == 'ms':
            value += 2.92 * hearing
        line = re.split(r'\n|\\n', before)[-1].strip()
        if TURN_TITLE.match(line) and len(line) < 65:
            value += 1.18 + 4.09 * hearing
        elif previous in {'Chairman', 'sir', 'Honor'}:
            value += 5.01 * hearing

    # Causal recognition: only clock fields already printed are visible.
    if word == ':':
        number = re.search(r'(?<!\d)(\d{1,2})$', before)
        if number:
            n = int(number.group(1))
            if n < 60:
                value += float(number.group(1) == '00')
                two_fields = bool(re.search(r'(?<!\d)\d{2}:\d{2}$', before))
                if re.search(r'\d{2}:\d{2}:\d{2}[,.]\d{3}', recent):
                    if two_fields or (n < 24 and re.search(r'\s\d{2}$', before)):
                        value += 1.04
                if re.search(r'\d{2}:\d{2},\d{3}\s+-->\s+\d{2}'
                             r'(?::\d{2})?$', before):
                    value += 7.26
        elif LABEL.search(before[-100:]):
            value += 0.19

    if word in COURTESY_TITLES:
        value += 0.6 * (word in {'Mr', 'Ms'})
        value += 2.09 * before.endswith('   ')
    if word in PUBLIC_ROLES:
        value += {'House': 1.56, 'Senator': 1.97}.get(word, 0.)
        value += 1.29 * (lower in {'the', 'this'})
    formal_cues = {'Chairman': 4.14, 'Thank': 6.44, 'today': 3.94}
    value += hearing * formal_cues.get(word, 0.)
    formal, conversational = OPENERS.get(word, (0., 0.))
    value += formal * hearing + conversational * speech

    # Familiar spoken constructions, rather than arbitrary token identities.
    if word == 'know' and lower == 'you':
        value += 2.37
    if word == 'think' and lower == 'i':
        value += 0.73
    if word == ',' and re.search(r'\byou know$', before, re.I):
        value += 2.75
    if word == 'of' and lower in {'kind', 'sort'}:
        value += 3.61 * speech
    if word == 'right' and lower == 'all':
        value += 4.58
    if word == 'then' and previous == 'And':
        value += 2.13
    if word == 'just':
        value += 0.51
    quote_verbs = {'was', 'is', 'are', 'am', "'m", '’m', "'re", '’re'}
    if word == 'like' and lower in quote_verbs:
        value += 4.24 * speech
    if word in {"'re", '’re'} and lower in {'we', 'they'}:
        value += 0.77
    if word == 'tonight':
        value += 2.13
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (doc, (before + token)[-400:]), float(value)

programs.haiku:
"""Layer-1 MLP component 3905: a "transcript paragraph break" detector.

What it responds to (from the training rows): the component is nearly silent in ordinary
prose and code, but fires inside multi-speaker transcripts written with literal escaped
newlines (backslash-n), such as congressional hearing text:

- the indentation token ("   ") that starts a new speaker's paragraph, right after a
  sentence ends on an escaped newline (".\\n    Mr. West"): the strongest response;
- the first word of that paragraph (" And", " So", " Thank"), also strong;
- the period after a speaker title or name ("Mr." / "Ms." / "Chairman."), and other
  sentence-final punctuation, moderately;
- the backslash that starts an escaped newline, weakly.

"In a transcript" is read causally from the text so far in the same document: at least
one speaker title (Mr, Ms, Chairman, Secretary, ...) and at least one escaped newline.

Values are the mean activations per class, fitted on 1024 training rows. Everything else
predicts 0. This is a readable approximation: it captures only part of the variance.
"""

TITLES = {"Mr", "Ms", "Mrs", "Dr", "Chairman", "Senator", "Secretary", "Representative", "Congressman"}
SENTENCE_END = {".", "?", "!", ".\\", "?\\", "!\\"}
CONJUNCTIONS = {" And", " So", " Thank"}

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        titles, escapes = 0, 0
        prev = ""
    else:
        titles, escapes = carry
        prev = tokens[-2]
    in_transcript = titles > 0 and escapes > 0

    if cur == "   ":
        value = 5.3 if in_transcript else 0.0
    elif prev == "   ":
        value = 2.4 if in_transcript else 0.0
    elif cur in SENTENCE_END and prev.strip() in TITLES:
        value = 5.0 if in_transcript else 0.6
    elif cur in SENTENCE_END:
        value = 2.3 if in_transcript else 0.0
    elif cur == " \\":
        value = 1.9 if in_transcript else 0.2
    elif cur in CONJUNCTIONS:
        value = 5.1 if in_transcript else 0.4
    elif cur == ",":
        value = 0.8 if in_transcript else 0.0
    else:
        value = 0.2 if in_transcript else 0.0

    # Update the transcript state with the current token.
    if cur.strip() in TITLES:
        titles += 1
    if cur == "n" and prev.endswith("\\") or cur.endswith("\\n"):
        escapes += 1
    return (titles, escapes), value

programs.sol:
"""Approximate a formatting-boundary signal, not the meanings of ordinary words.

Positive cues include key/value punctuation, inline list labels, and TeX
structure. Line-ending punctuation behaves differently from punctuation on
its own. Starts of documents and repeated middle-dot filler have negative
responses. Constants are fitted on training examples; lexical variation
within these categories is deliberately left unexplained.
"""
import re

READS = ()


def estimate(token, before, first):
    s = token.strip()
    if first:
        if s.isdigit():
            return -0.294
        return -0.174 if s[:1].isalpha() else -0.102
    if '\n' in token and s in ('.', ':', ')'):
        return 0.004

    # Keys and the punctuation introducing their values.
    if s == '\\":':
        return 0.384
    if s == "':":
        return 0.288
    if s == '":':
        return 0.376 if re.search(r'\b(?:name|title|id)$', before) else 0.661
    if s == '：':
        return 0.060
    if s == ':':
        if token[:1].isspace():
            return 0.013
        if before.endswith(('http', 'https', 'ftp', ':', '/', '\\')):
            return 0.0
        if re.search(r'\d$', before):
            return 0.146
        if re.search(r'''[,{]\s*[\w"']+$''', before):
            return 0.523
        line = before.rsplit('\n', 1)[-1]
        if ':' in line and not re.search(r'[/\\]', line):
            return 0.488
        if re.search(r'(?:^|\s)[A-Za-z]$', before):
            return 0.105
        return 0.086 if re.search(r'\s[^\W\d_][\w-]*$', before) else 0.188

    # Small enumerators and abbreviated labels, rather than sentence endings.
    if s in ('.', '．'):
        if re.search(r'(?:^|\s)[1-9]$', before):
            return 0.429 if re.search(r'[.:)] +[1-9]$', before) else 0.059
        if re.search(r'\d$', before):
            return 0.003
        if re.search(r'(?:^|\s)[ivxIVX]{1,5}$', before):
            if re.search(r'[.:)] +[ivxIVX]{1,5}$', before):
                return 0.465
            return 0.084
        if re.search(r'(?:^|\s)[A-Za-z]$', before):
            return 0.176 if before[-1].islower() else 0.054
        return 0.027 if re.search(r'\.[A-Za-z]$', before) else -0.009
    if s in (')', '.)'):
        if re.search(r'(?:^|\s)\(?[a-dA-DivxIVX]{1,4}$', before):
            return 0.301
        if re.search(r'(?:^|\s)\([1-9]\d?$', before):
            at_line_start = re.search(r'(?:^|\n)\s*\([1-9]\d?$', before)
            return -0.249 if at_line_start else 0.470
        return 0.043 if re.search(r'\d$', before) else -0.035

    if s == '"' and token.startswith(' '):
        if before.endswith(('":', '\\":')):
            if before.endswith('name":'):
                return 0.187
            if re.search(r'(?:command|type)":$', before):
                return 0.795
            return 0.376
        return 0.117 if before.endswith((':', '=', '=>', '+')) else -0.008
    if s == "'" and token.startswith(' '):
        if before.endswith((':', '=', '=>', '+')):
            return 0.156
    if s == '{"':
        return 0.105
    if s in ('="', "='"):
        return 0.172

    # Typesetting commands and a few recognizable page-formatting cues.
    if s == '{' and re.search(r'\\(?:begin|end)$', before):
        return 0.830
    if s == 'align' and before.endswith('{'):
        return 0.971
    if s == 'style' and before.endswith('\\display'):
        return 0.755
    if s == 'link' and before.endswith('{@'):
        return 0.496
    if s == '··' and before.endswith('·'):
        return -1.105
    if ((s.lower() == 'more' and re.search(r'(?:Read|read|See|View)$', before))
            or (s == 'Reading' and before.endswith('Continue'))
            or (s == 'information' and before.endswith('More'))):
        return 0.715
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = estimate(token, before, first)
    return (doc, (before + token)[-160:]), value

