programs.sol:
"""A multilingual c / ц fragment detector.

Short Cyrillic ц pieces give a negative response. Latin c does so chiefly
in Central/Eastern European and Turkish contexts, inferred from recent
completed-word frequencies and distinctive accents. Length and nominal
suffixes scale the response; ch has an opposite, positive contextual term.
The letters č/ć give a weaker negative response. A following vowel piece
can complete an unfinished c syllable and inherit some of its response.
"""
from functools import lru_cache
from math import exp
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'pl', 'cs', 'sk', 'hu', 'tr', 'de', 'da',
             'fr', 'es', 'it', 'pt', 'ro', 'nl', 'sv')
C_GAIN = (0., 4.5, 4.6, 3., 2.8, 1.1) + (0.,) * 9
SLAVIC_ACCENTS = frozenset('ąćęłńśźżčďěňřšťůžľĺŕ')
HUNGARIAN_ACCENTS = frozenset('őű')
TURKISH_ACCENTS = frozenset('ğış')
ACCENT_GAIN = 2.0
CH_GAIN = 1.95
CONTINUATION_GAIN = (0.75, 0.79)


@lru_cache(maxsize=65536)
def evidence(word):
    if len(word) < 2:
        return (0.,) * len(LANGUAGES)
    return tuple(max(0., zipf_frequency(word, lang) - 2.)
                 for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scores = (4.,) + (0.,) * (len(LANGUAGES)-1)
        word, accent, previous = '', 0., None
    else:
        _, scores, word, accent, previous = carry
    text = prefix.token_strings[-1].lower()
    accent *= .985
    if any(c in SLAVIC_ACCENTS for c in text):
        accent = 1.
    elif any(c in HUNGARIAN_ACCENTS for c in text):
        accent = max(accent, .65)
    elif any(c in TURKISH_ACCENTS for c in text):
        accent = max(accent, .4)
    for char in text:
        if char.isalpha():
            word = (word + char)[-40:]
        elif word:
            ev = evidence(word)
            if max(ev) > 0:
                scores = tuple(.85*s + e for s, e in zip(scores, ev))
            word = ''

    s = text.strip()
    boundary = .75 if text[:1].isspace() else 1.
    value, unfinished = 0., None
    if 'ц' in s or 'c' in s:
        cyrillic = 'ц' in s
        a = s.rfind('ц' if cyrillic else 'c')
        after = len(s)-a-1
        back_vowel = s[a+1:a+2] in ('a', 'o', 'u', 'а', 'ы')
        if cyrillic:
            value = -4.27 * exp(-.4*a - .75*after) * boundary
            if back_vowel:
                value *= 1.5
            # Full nominalization suffixes mute the letter-level response.
            if s.endswith(('ции', 'ция', 'цию', 'ций', 'цион')):
                value *= .25
            # Genitive-plural and surname endings retain it.
            if s.endswith(('цов', 'цев')):
                value = -4.25 * exp(-.3*a) * boundary
        else:
            weights = [exp(x-max(scores)) for x in scores]
            gain = sum(w*g for w, g in zip(weights, C_GAIN))/sum(weights)
            gain = max(gain, ACCENT_GAIN*accent)
            value = -gain * exp(-.2*a - .5*after) * boundary
            if back_vowel:
                value *= 1.5
            if 'cz' in s:
                value *= .1
            if 'ch' in s:
                shape = exp(-.2*a - .6*max(0, after-1))
                shape *= 1. if boundary < 1 else .35
                value = -.15 + CH_GAIN * (gain/4.5) * shape
        unfinished = (value, after, cyrillic)
    elif previous is not None and text.isalpha():
        old_value, tail, cyrillic = previous
        vowels = 'аеёиоуыэюяіїє' if cyrillic else 'aeiouyąęáéíóúýőűj'
        if tail <= 1 and text[0] in vowels:
            value = CONTINUATION_GAIN[cyrillic] * min(0., old_value)
            value *= exp(-.4*(len(text)-1)) * (.4 if tail else 1.)

    if 'č' in s or 'ć' in s:
        a = max(s.rfind('č'), s.rfind('ć'))
        value -= exp(-.25*a-.6*(len(s)-a-1)) * (1. if boundary == 1 else .7)
    return (doc, scores, word, accent, unfinished), value

"""Local spelling joins, with positive Chinese season/name/scenery roots.

Negative responses occur where a g/k/q/j-ending fragment is continued by a
short i-starting fragment.  Positive responses cover Chinese season-month order
(Meng, Zhong, Ji), the surnames of Confucius and Mencius, and scenery;
the single-character roots for fear and anxiety form another positive island.
Thai stop-closed syllables and Latin nasal rhymes supply smaller local modes.
This is a sparse approximation: most tokens contribute essentially zero.
"""

import re
import unicodedata
from functools import lru_cache
import cedict

READS = ()


@lru_cache(maxsize=4096)
def chinese_value(text):
    value = 0.0
    # First, middle, and last month within a season.
    if text in ('孟', '仲', '季'):
        value += 2.5
    if text in ('孔', '孟'):
        value += 3.8
    if text == '季':
        value += 1.9
    elif text in ('季节', '季節', '四季'):
        value += 2.7
    elif len(text) == 2 and text[0] in '春夏秋冬' and text[1] == '季':
        value += 1.1
    elif text.startswith('季'):
        value += 0.8
    # The two single-character roots in common fear/anxiety compounds.
    if text in ('恐', '焦'):
        value += 2.6
    if text == '恐怕':
        value += 2.0
    if '景' in text:
        gloss = ' '.join(cedict.glosses(text)).lower()
        if any(word in gloss for word in ('scenery', 'landscape', 'panoram')):
            value += 2.5 if text == '景' else 1.3
    return value


def spelling_join(previous, text):
    s, p = text.lower(), previous.lower()
    # Thai short-vowel + final-stop joins after ก (k) or จ (ch).
    if text == 'ัด' and previous.endswith(('ก', 'จ')):
        return -3.5
    if text in ('ิด', 'ิต') and previous.endswith('ก'):
        return -3.6
    # Velar consonants followed by a nasal rhyme (kong, kung).
    if s in ('ong', 'ung') and p.strip() in ('g', 'k', 'q', 'kh'):
        return 1.4 if s == 'ong' else 0.8
    if s == 'ng' and p and not p[-1].isascii():
        vowel = unicodedata.normalize('NFD', p[-1])[0]
        if vowel in 'aeiou' or p[-1] in 'æøœ':
            return 1.5
    if not (s.startswith('i') and s.isascii() and s.isalpha()
            and p.endswith(('g', 'k', 'q', 'j'))):
        return 0.0
    # A final -ing generally has no separately sounded g.
    if p.endswith('ing'):
        return 0.0
    after_g = p.endswith('g')
    if s == 'is':
        return -3.4 if after_g else -1.0
    if re.fullmatch(r'iss[ae]?', s):
        return -4.6 if after_g else -0.8
    if s in ('ick', 'ikk'):
        return -4.5 if after_g else -0.7
    if s == 'ik':
        return -2.2 if after_g else -0.5
    if s.startswith('is') and len(s) <= 4:
        return -1.2 if len(p.strip()) <= 2 else -0.2
    if re.fullmatch(r'i(?:c|t{1,2}|re?)', s):
        if after_g and p.endswith('ag'):
            return -2.1
        return -0.6 if after_g else -0.2
    if 1 < len(s) <= 3 and s[1] not in 'aeiou':
        return -0.5 if after_g else -0.1
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = chinese_value(text)
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        value += spelling_join(prefix.token_strings[-2], text)
    return None, value

programs.haiku:
"""Candidate v4: exact-token lookup over concept groups, plus one context rule.

Mostly zero. It fires on a few single Chinese characters (surnames such as 孟 孔 仲 焦,
and 季 season / 景 scene), on words built from them (季节, 四季, 景色, 恐怕), and on
Latin fragments split out of longer words (gis, GIS, agit), which push it negative.
The fragment "isk" pushes it negative only after "q" (as in Qiskit).
"""
READS = ()

# Single Chinese characters: surnames, plus 季 (season) and 景 (scene).
CHAR_VALUES = {
    "孟": 5.0, "季": 4.0, "孔": 4.0, "仲": 3.0, "恐": 3.0, "景": 2.5, "焦": 2.5,
    "彦": 1.5, "慶": 1.5, "姜": 1.0, "孤": 1.0, "句": 1.0, "韩": 1.0, "庆": 1.0,
    "伯": 0.7, "希": 0.5, "圣": 0.5, "苦": 0.5,
}
# Words built on those characters.
WORD_VALUES = {
    "季节": 2.5, "四季": 2.5, "旺季": 3.0, "春季": 1.5, "冬季": 1.5, "夏季": 1.0,
    "景色": 1.5, "美景": 1.5, "全景": 2.0, "情景": 1.2, "风景": 0.8,
    "困难": 1.7, "恐怕": 2.2,
}
# Latin fragments split out of longer words; they pull the output negative.
FRAGMENT_VALUES = {"gis": -3.0, "GIS": -4.0, " GIS": -3.5, "agit": -2.5, "bbbb": -1.3, "IMP": -1.2}

VALUES = {**CHAR_VALUES, **WORD_VALUES, **FRAGMENT_VALUES}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "isk" and len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip() in ("q", "Q"):
        return carry, -1.2
    return carry, VALUES.get(s, 0.0)

programs.sol:
"""Predict surface punctuation responses, not word-specific variation.

Full stops strengthen with the gap since a dot/question/exclamation mark;
capital initials (especially after capitalized words) boost them. Numeric endings,
formatting, recent newlines and document position adjust their strength.
Middle dots respond positively when attached to Han or kana in the usual
name-separator spelling. Document-initial 'Title' gets a positive response;
a colon immediately following it is a separate large negative exception.
"""
import math
import re
import regex

READS = ()


def response(token, tail, gap, lines, position):
    s = token.strip()
    # The explicit title label at the beginning of a document.
    if token == 'Title' and position == 0:
        return 1.34
    if token == ':' and position == 1 and tail == 'Title':
        return -15.75
    # Script-sensitive middle dots, common in transliterated names.
    if token == '·':
