    (COLLECTION, -0.1016, -1.2686),
    (GROUP, 0.0789, -1.0723),
    (PART, -0.1202, -0.7474),
    (MEASURE, -0.2145, -0.1961),
    (FOREIGN_COLLECTION, -0.7086, -1.912),
    (FOREIGN_MEASURE, -0.1684, -0.2811),
