"""Estimate a document-initial pulse, with a nearly silent interior.

The first token after an attention reset usually has a large negative value.
Its size varies with typography, script, capitalization and function-word
class. These broad classes approximate the pulse, not its individual lexical
preferences. Subsequent tokens are approximated by zero.
"""
import unicodedata
import regex

READS = ()
ARTICLES = frozenset('a an the'.split())
PRONOUNS = frozenset(
    'i me my mine we us our ours you your yours he him his she her hers '
    'it its they them their theirs this that these those'.split()
)
CONJUNCTIONS = frozenset(
    'and or but nor so yet if because although unless while when than whether'.split()
)


def initial_pulse(s):
    if s == '<|im_start|>':
        return -5.10
    t = s.strip()
    value = -4.76
    if not t:
        if '\n' in s or '\r' in s:
            value += 2.81
        elif '\t' not in s:
            value += 2.73
        if '\t' in s:
            value -= 2.11
        if '\r' in s:
            value -= 2.21
        if '\xa0' in s:
            value += 4.46
        if len(s) > 1 and s.count(' ') == len(s):
            value -= 2.19
    elif t.isdecimal():
        value += 1.60
    elif t.isascii() and t.isalpha():
        value += 0.66
        if t.istitle():
            value -= 1.17
        if len(t) > 1 and t.isupper():
            value -= 0.58
        word = t.lower()
        if word in ARTICLES:
            value += 1.24
        if word in PRONOUNS:
            value -= 0.64
        if word in CONJUNCTIONS:
            value += 1.08
    elif regex.search(r'\p{Script=Han}', t):
        value += 1.49
    elif any(c.isalpha() and not c.isascii() for c in t):
        value += 0.94
    elif all(unicodedata.category(c)[0] in 'PS' for c in t):
        value += 2.06

    if t == ',':
        value -= 1.09
    if t == '.':
        value += 0.74
    if t and t[0] in ')]}':
        value += 0.70
    if '\ufffd' in s:
        value += 1.10
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = initial_pulse(prefix.token_strings[-1]) if first else 0.0
    return document, value

"""Estimate early line boundaries, with one patent-number marker.

The first single line ending contrasts prose-like endings with short titles,
pipe-separated records, and website-ending lines. Opening-token capitalization
and spacing adjust the estimate. Later newlines receive small corrections.
'Pat. No' and 'Patent No' get a separate positive pulse. Everything else is zero:
this omits the component's ordinary word-specific background responses.
