    token = prefix.token_strings[-1]
    value = 0.0
    if carry is None or carry[0] != doc:
        upper = token[:1].isupper()
        space = token.startswith(' ')
        special = token.startswith('<|')
        lines, line = 0, ''
    else:
        _, upper, space, special, lines, line = carry

    breaks = token.count('\n')
    if breaks:
        if breaks > 1:
            value = 0.02
        elif lines == 0:
            ending = token.rstrip('\r\n ')
            if token == '\n' and not line:
                value = 0.52
            elif special:
                value = -0.005
            elif token == '\n' and len(line) < 120 and ' | ' in line:
                value = -2.4
            elif token == '\n' and len(line) < 120 and any(
                mark in line.strip() for mark in (' - ', ' – ', ' — ')
            ):
                value = -1.4
            elif token == '\n' and URL_END.search(line):
                value = -1.5
            elif any(c in '.?!。！？)“”' for c in ending):
