            elif upper and len(line) < 85:
                value = -0.37 if token == '\n' else -0.05
            else:
                value = 0.22 if len(line.split()) >= 8 else 0.035
        else:
            value = -0.025 if line[:1].isupper() and lines >= 2 else 0.0
        lines += breaks
        line = token.rsplit('\n', 1)[-1]
    else:
        if token.strip().casefold() == 'no' and PATENT.search(line[-200:].rstrip()):
            value = 1.4
        line += token

    return (doc, upper, space, special, lines, line), value

"""A detector of short metadata formulas, especially source-code authorship.

Positive: author/parameter tags in comments and 'Created by' or posting
bylines. Negative: dated clock suffixes and the df/ax label prefixes in
non-breaking-space-separated mathematical reference lists. Smaller rules
recognize web-page counters, search/learning widgets and type-checker
directives. Tags are stronger near a comment's start and in PHP-like code.
Unrecognized text gets zero. A bounded recent-text buffer resets between
documents.
"""
import re
import math

READS = ()
BYLINES = {
    'posted': 4.7,
    'published': 2.6,
    'edited': 2.3,
    'written': 3.0,
    'submitted': 1.0,
    'uploaded': 4.0,
    'liked': 4.4,
    'asked': 1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0
