    body = history[start + 3:] if in_comment else history[-200:]

    if word == 'by':
        match = re.search(r'([A-Za-z]+)\s*$', history)
        previous = match.group(1) if match else ''
        line = re.split(r'\n|<\|endoftext\|>', history)[-1].strip()
        label = re.fullmatch(
            r'[\W\d]*(?:(?:Last|Originally)\s+)?[A-Za-z]+', line, re.I
        )
