            if in_comment:
                value = 18.0 if len(body) < 30 else 9.0
            elif label or re.search(r'//\s*Created\s*$', history):
                value = 7.5
        elif previous.lower() in BYLINES and label:
            value = BYLINES[previous.lower()]
            if previous == 'posted':
                value = 3.1
            elif previous.lower() == 'posted' and 'Originally' in line:
                value = 3.1
        elif re.search(r'\bpost shared\s*$', history):
            value = 1.3
        elif re.search(r'Published[^\n]{0,60}\|\s*$', history):
            value = 1.4
    elif token == ' Created' and in_comment:
        value = 10.0 if len(body) < 25 else 3.0
    elif word == '@' and (in_comment or re.search(r'\*\s*$', history)):
        first_line = re.search(r'\n\s*\*\s*$', body)
        value = 1.8 if first_line and len(body) < 25 else 0.6
    elif token == '@author':
        value = 5.8
    elif token == ':' and history.endswith('@author'):
        value = 10.4
    elif history.endswith('@'):
        if word == 'author':
            value = 8.0 + 5.0 * math.exp(-len(body) / 50.0)
        elif word == 'Author':
            value = 4.3
        elif word == 'param':
            fresh = math.exp(-len(body) / 60.0)
            value = 2.5 + 4.0 * fresh
            if '$' in history:  # PHP-style variable syntax.
                value += 2.5 + fresh
        elif lower in {'return', 'returns'}:
            value = 0.8 + math.exp(-len(body) / 60.0)
            if '$' in history:
                value += 0.9
        elif lower in {'type', 'var'}:
            value = 4.3 if lower == 'var' and '$' in history else 1.5
        elif lower in {'see', 'link', 'name', 'throws', 'since', 'version'}:
            value = 0.6
    elif lower == 'results' and history.lower().endswith('now showing'):
        value = -3.5
    elif word == 'Homework' and history.endswith('assignment'):
        value = -6.2
    elif word == 'Volume' and history.endswith('Forum:'):
        value = -7.8
    elif lower == 'timer' and re.search(
        r'(?:Thank you for using the|HideShow)\s*$', history
    ):
        value = -1.8
    elif lower == 'item' and history.endswith('link to this'):
        value = 4.0
    elif lower == 'ignore' and re.search(r'#\s*type:\s*$', history):
