        value = -4.4
    elif word == 'Worksheet' and history.endswith('Math\n'):
        value = -2.8
    elif word == 'Worksheet' and history.endswith('Worksheet\n'):
        value = -1.2
    elif lower == 'param' and re.search(r'(?:<|\\|:)\s*$', history):
        value = 1.2 if history.endswith(':') else 2.3
    elif word in {'df', 'ax'} and history.endswith('\xa0'):
        # Definition and axiom labels in mathematical reference lists.
        value = -9.1 if word == 'df' else -7.5
