        return None, -1.0
    return None, 0.0

"""layers.1.mlp.down_proj:3920 -- a comma detector whose sign tracks what the comma follows.

This component fires almost only on commas (",", the fullwidth "，" and the Japanese
"、"). Its activation is positive when the comma closes a piece of running prose that
is about to continue, and negative when the comma sits inside code or a number:

  - a comma right after a strong clause connective ("and,", "or,", "which,", "who,")
    is clearly positive (~+1.0);
  - a Japanese comma "、" (after a particle or clause) is positive (~+0.45);
  - a comma after a weak connective or auxiliary ("then,", "that,", "is,", "to,", "so,")
    is mildly positive (~+0.2);
  - a comma inside a number ("1,000") or a code line (after "self", "(", "_", "=") is
    negative (~-0.17);
  - any other comma is about zero (~+0.03).

Every other token predicts 0. Document starts and colons are not modelled: their
activations depend on the specific token, not on a readable class.
The step is stateless: it reads only the newest token and the one before it.
"""

READS = ()

COMMAS = {",", "，", "、"}
STRONG_CONNECTIVES = {"and", "or", "but", "which", "who", "whom"}
WEAK_CONNECTIVES = {
    "then", "so", "now", "is", "are", "was", "be", "may", "to", "of", "that", "if",
    "when", "while", "because", "than", "as", "also", "however", "thus", "therefore",
}
CODE_MARKS = set("_()[]{}=.;")


def _is_code_or_number(prev):
    """True for a previous token that is a number, or looks like code: identifiers, brackets."""
    if prev.isdigit():
        return True
    return "self" in prev or any(ch in CODE_MARKS for ch in prev)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in COMMAS:
        return None, 0.0
    if token == "、":
        return None, 0.45
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    word = prev.lower()
    if word in STRONG_CONNECTIVES:
        value = 1.0
    elif word in WEAK_CONNECTIVES:
        value = 0.2
    elif _is_code_or_number(prev):
        value = -0.17
    else:
        value = 0.03
    return None, value

programs.sol:
"""Approximate a detector of indentation-only empty lines.

Space/tab padding followed by a newline is strongly negative when it starts
an empty line, not when it trails text. Short padding is strongest; longer
padding is weaker, with an extra response for four-space alignment. Packed
line breaks and whitespace-only preceding newline tokens weaken it.
Ordinary text is zero;
empty comment/quote/diff lines and initial newlines get smaller negatives.
"""
from math import log

READS = ()


def indentation_response(indent):
    if indent.strip(' \t'):
        return -0.9  # Non-ASCII whitespace is not ordinary indentation.
    tabs = indent.count('\t')
    spaces = len(indent) - tabs
    if tabs:
        return -7.6 + 1.6 * log(tabs) + (3.2 if spaces else 0.0)
    return -2.0 - 8.2 / (1 + (spaces / 3.5) ** 2.75) - (
        1.8 if spaces % 4 == 0 else 0.0
    )


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    blank, after_newline = (True, False) if first else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if token.isspace() and token.endswith('\n'):
        lines = token.replace('\r', '').split('\n')[:-1]
        n = len(lines)
        padded = [s for s in lines if s]
        if padded:
            base = indentation_response(padded[-1])
            if n == 1:
                if first:
                    value = 0.4 * base
                elif after_newline:
                    previous = prefix.token_strings[-2]
                    value = base * (0.8 if previous.isspace() else 1.0)
                elif blank:
                    value = 0.3 * base
                else:
                    value = 0.08
            elif lines[-1]:
                value = base * (0.6 if n == 2 and not lines[0] else 0.3)
            elif blank:
                value = base * (0.35 if after_newline else 0.1)
        elif first:
            value = -3.5 if '\r' in token else -1.05
        elif blank:
            value = -1.5 / (n * n)
    elif token.endswith('\n') and token.strip() in ('*', '>', '+') and blank:
        value = -0.9
    if '\n' in token:
        blank = not token.rsplit('\n', 1)[-1].strip()
    else:
        blank = blank and not token.strip()
    return (document, blank, token.endswith('\n')), value

"""A spelling-sensitive detector for short pre-/pere-/pr- fragments.

Strongest in Slavic spellings, including Czech př- and Polish prz-.
A fragment continued in another token has a different strength from a
merged fragment. Recent Slavic diacritics disambiguate Latin pre-/pro-.
Greek par-/per-/pro- syllables and a few negative responses are included.
This is not a detector for every complete word with one of these prefixes.
"""
from anyascii import anyascii
import regex

READS = ()
SLAVIC_MARKS = frozenset('čďěľĺňřŕšťůž')


def response(s, previous, word, slavic):
    t = s.strip().lower()
    a = anyascii(t)
    b = anyascii(previous.lower())
    w = anyascii(word)
    attached = bool(s and not s[0].isspace() and t and t[0].isalpha())
    if t == 'ą' and b.endswith('pi') and attached:
        return -4.7
    if regex.search(r'\p{Script=Cyrillic}', t):
        if attached:
            if w.endswith('per') and a.startswith('e'):
                if a.startswith(('ed', 'ep')):
                    return 16.0
                if a.startswith('en'):
                    return 13.5
                return 6.9 if a.startswith('ech') else 11.3
            if w.endswith('pe') and a.startswith('r'):
                return 15.0 if a.startswith('re') else 6.0
            if word.endswith('пі') and t.startswith('д'):
                return 4.1
            if b.endswith('pr'):
                if a.startswith('y'):
                    return -5.3
                if a.startswith('ess'):
                    return 0.0  # press-, rather than the Slavic pre- prefix
                if a.startswith('er'):
                    return 7.5
                if len(t) <= 3:
                    return {'e': 4.3, 'o': 1.4, 'i': 0.3}.get(a[:1], 0.0)
            if b.endswith('p') and a.startswith('r'):
                return {'re': 1.2, 'ro': 0.6, 'ri': 0.9}.get(a[:2], 0.0)
            if b.endswith('per') and a.startswith('s'):
                return 1.6
        if t == 'пер' and word and attached and word not in {'не', 'по'}:
            return 0.0
        if t == 'пере':
            return 6.0 if s.strip().startswith('П') else 8.5
        return {'перед': 11.2, 'перев': 6.5,
                'пер': 2.9, 'пред': 2.2, 'преп': 4.9, 'прек': 4.9,
                'през': 2.1, 'пре': 1.1, 'про': 1.2,
                'под': 0.75}.get(t, 1.06 if t in {'от', 'отд'}
                               and s[:1].isspace() else 0.0)
    if regex.search(r'\p{Script=Greek}', t):
        if attached:
            if word.endswith('πα') and a.startswith('y'):
                return -5.5
            if w in {'pa', 'pe'} and a.startswith('r'):
                return 4.7
            if word.endswith('πρ') and a.startswith(('o', 'e')):
                return 5.4
            if word.endswith(('παρ', 'περ')):
                return {'i': 4.0, 'a': 3.5, 'o': 5.2}.get(a[:1], 0.0)
            if word.endswith('π') and a.startswith('o'):
                return 0.5
        return 0.0
    if attached and t.startswith('ř') and b.endswith('p'):
        return 4.5
    if 'ř' in t and a == 'pr':
        return 4.6
    if attached and word.endswith('př'):
        return {'e': 9.3, 'i': 2.2}.get(a[:1], 0.0)
    if attached and b.endswith('pr') and t.startswith('ů'):
        return 4.1
    if a in {'prz', 'prze', 'przed', 'przec', 'przez', 'przy'}:
        return {'prz': 4.9, 'prze': 8.2, 'przed': 6.2,
                'przec': 9.1, 'przez': 1.5, 'przy': 2.7}[a]
    if attached and w.endswith('prz'):
        if a.startswith('ec'):
            return 8.9
        return {'e': 4.1, 'y': 3.0}.get(a[:1], 0.0)
    if attached and b.endswith('pr') and a.startswith('z'):
        return 13.4 if a.startswith('ze') else 6.2
    if slavic and a in {'pre', 'pred', 'prev', 'prem', 'pro', 'pri'}:
        return {'pre': 6.4, 'pred': 7.0, 'prev': 4.3,
                'prem': 3.7, 'pro': 1.3, 'pri': 3.6}[a]
    if attached and b.endswith('pr') and a.startswith('ere'):
        return 2.8
    if attached and b.endswith(('p', 'pe')) and a.startswith('er'):
        return 1.2 if a.startswith('ere') else 0.3
    return {'pred': 0.3, 'pod': 0.45, 'pro': 0.18}.get(a, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, level = '', '', 0.0
    else:
        _, tail, previous, level = carry
    s = prefix.token_strings[-1]
    level = max(level * 0.98,
                float(any(ch in SLAVIC_MARKS for ch in (s + previous).lower())))
    match = regex.search(r'\p{L}+$', tail)
    word = match.group().lower() if match else ''
    value = response(s, previous, word, level > 0.25)
    return (doc, (tail + s)[-16:], s, level), value

programs.haiku:
"""Word-start rule: the letters of the current word so far (first 5 at most) spell the
opening of a 'pere-/pre-/prze-' word (Russian перед, пере-; Czech/Polish před, před, przed, pře-)."""
READS = ()

def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != carry[1]:
        word = ""
    else:
        word = carry[0]
    for ch in prefix.token_strings[-1].lower():
        word = word + ch if ch.isalpha() else ""
    if len(word) > 5:
        value = 0.0
    elif word.startswith(("перед", "przed")):
        value = 10.0
    elif word.startswith(("пере", "prze", "pře", "před")):
        value = 9.0
    elif word.startswith(("пер", "prz")):
        value = 3.5
    elif word.startswith("př"):
        value = 4.5
    elif word.startswith("пре"):
        value = 2.0
    elif word in ("от", "под", "про"):
        value = 1.0
    else:
        value = 0.0
    return (word, prefix.document_ids[-1]), value

programs.sol:
"""An L-and-learning detector, not a general education detector.

Learning words are positive, but 'machine learning' and related technical
phrases are weak.  Adjective/determiner context adjusts their strength.
Split learner words and the spelling 学習 also count.
L followed by a small index or a norm exponent is another positive pattern.
'Learn more' and a document-opening 'Title:' have negative responses.
Many other, idiosyncratic subword responses are deliberately unmodeled.
"""
import re
import unicodedata
from functools import lru_cache
import wordnet

READS = ()
LABEL = re.compile(r'([A-Za-z]+|[λℓ]|\\ell|\\lambda)([ \t_\-^{}~/]*)\Z')
DETERMINERS = {
    'a', 'an', 'the', 'this', 'that', 'these', 'those', 'my', 'your',
    'his', 'her', 'its', 'our', 'their',
}
ML_METHODS = {
    'machine', 'deep', 'reinforcement', 'supervised', 'unsupervised',
    'active', 'federated',
}


@lru_cache(maxsize=1024)
def learning_context(word):
    if word in ML_METHODS:
        return 0.06
    if word in {'after', 'before', 'while', 'without', 'by', 'just'}:
        return 0.45
    if word in {'blended', 'language', 'collaborative'}:
        return 2.9
    if word in DETERMINERS:
        return 1.8
    if 'adjective' in wordnet.parts_of_speech(word):
        return 1.85
    return 1.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = b'', '', 0
    else:
        _, tail, previous, position = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    text = tail.decode('utf-8', errors='replace')
    word, before = token.strip().lower(), previous.strip().lower()
    value = 0.0

    if word.strip('.-') == 'learning':
        value = learning_context(before.strip('-'))
    elif word in {'learner', 'learners', 'learn'}:
        value = {'learner': 1.55, 'learners': 2.6, 'learn': 0.14}[word]
    elif word == 'lear' and token[:1].isspace():
        value = 1.8
    elif word in {'ners', 'ner'} and text.lower().endswith('lear'):
        value = 4.8 if word == 'ners' else 3.0
    elif word in {'ear', 'earning', 'ern'} and text.endswith('L'):
        value = {'ear': 4.0, 'earning': 2.4, 'ern': 5.2}[word]
    elif word in {'学习', '的学习', '學習'}:
        value = 0.8
    elif word in {'習', '习'} and text.endswith(('学', '學')):
        value = 5.5
    elif word == 'more' and before in {'learn', 'learning'}:
        value = -4.4 if previous.strip() == 'Learn' else -3.4
    elif word == '_rate' and before == 'learning':
        value = 1.75
    elif token == ':' and previous == 'Title' and position == 1:
        value = -3.48

    # Recover a digit whose UTF-8 bytes straddle a token boundary.
    if '\ufffd' in token:
        joined = (tail + raw).decode('utf-8', errors='replace')
        if joined and joined[-1].isdigit():
            word, text = joined[-1], joined[:-1]
    number = None
    if len(word) == 1:
        try:
            number = unicodedata.digit(word)
        except (TypeError, ValueError):
            pass

    if number is not None or token in {'p', 'r', '^', '^{'}:
        match = LABEL.search(text)
        if match:
            label, syntax = match.groups()
            small = number in {1, 2, 3}
            if number is not None:
                if label in {'L', 'l', 'ℓ', r'\ell'}:
                    if not syntax:
                        value = 3.2 if small else 1.4 if number == 4 else 0.6
                    elif syntax.isspace():
                        value = 3.6 if number == 2 else 0.7
                    elif re.fullmatch(r'}*[_^]{\-?', syntax):
                        value = 2.8 if small else 0.2
                        if '^' in syntax or '-' in syntax or syntax.startswith('}'):
                            value *= 0.55
                    elif syntax in {'-', '/'}:
                        value = 1.5 if syntax == '-' and small else 0.5
                    if 'SUPERSCRIPT' in unicodedata.name(word, ''):
                        value = min(value, 1.0)
                elif label in {'λ', r'\lambda'}:
                    value = 0.6 if small else 0.0
                elif label.lower() in {'level', 'layer'}:
                    value = 1.0 if small else 0.0
                elif not syntax and previous.strip().endswith('L'):
                    value = 2.3 if small else 0.3
                elif not syntax and label.endswith('Cl'):
                    value = 0.9 if number in {2, 3} else 0.0
                elif not syntax and label.endswith('l'):
                    value = 0.25 if small else 0.1
            elif label in {'L', 'l', 'ℓ', r'\ell'}:
                if token == '^' and not syntax:
                    value = 3.6
                elif token == '^{' and not syntax:
                    value = 1.5
                elif token in {'p', 'r'}:
                    value = 6.0 if '^' in syntax else 1.9

    return (doc, (tail + raw)[-64:], token, position + 1), float(value)

"""Approximate a sparse family of phrase-completion responses.

Positive: indefinite collection/category phrases ending in 'of'. Negative:
exhaustive 'all' constructions, a few productive -able derivations, literal
ownership compounds, and split mathematical/programming expressions. The
rolling text is only a short look-behind, cleared at document boundaries.
Other contexts use a small background prediction. At a document's first
token it also uses case, script, and two broad WordNet meaning classes.
Most diffuse variation remains unexplained.
"""
import re
import regex
import wordnet

READS = ()
COLLECTIONS = {'group', 'family', 'class', 'set', 'type'}
SEARCH = {'find', 'finds', 'finding', 'determine'}
GATHER = {
    'get', 'getting', 'select', 'selecting', 'list', 'listing',
    'generate', 'generating', 'retrieve', 'collect', 'collecting',
}
ABLE_STEMS = {'scroll', 'fill', 'close', 'drink', 'bill', 'count'}


def activation(old, token):
    word = token.strip().lower()
    if word not in {'of', 'de', 'all', '_all', 'able', 'holder', 'holders',
                    'ers', 'symbol', 'gl', 'possible', 'example',
                    'module', 'flow', 'box'}:
        return None
    m = re.search(r'([A-Za-z]+)$', old)
    raw = m.group(1) if m else ''
    previous = raw.lower()
    words = re.findall(r'[a-z]+', old.lower())[-5:]
    before = words[-2] if len(words) > 1 else ''
    copula = len(words) > 2 and words[-3] in {'is', 'are', 'was', 'be'}
    if word == 'of':
        if previous == 'type' and before == 'what':
            return -0.85
        if previous in COLLECTIONS:
            if before == 'a':
                if previous == 'set':
                    return 0.75 if copula else 0.45
                if previous == 'type':
                    return 0.85 if copula else 0.5
                return 0.85
            if previous == 'family':
                return 0.4
            if before == 'the':
                return -0.1
            if before in {'finite', 'infinite'} and previous == 'set':
                return 0.85
            if before in {'this', 'any'}:
                return 0.55 if previous in {'set', 'group'} else 0.2
        if previous == 'types' and before in {'two', 'three'}:
            return 0.6 if copula else 0.15
        if previous in {'variety', 'couple', 'bunch', 'lot', 'piece', 'snippet'}:
            return -0.2
        if previous == 'collection' and before == 'a':
            return 0.2
    elif word == 'de' and previous == 'grupo' and before == 'un':
        return 0.8
    elif word in {'all', '_all'}:
        if previous in SEARCH:
            return -1.5
        if previous in GATHER:
            return -0.65
        if previous == 'without':
            return -0.4
        if previous == 'of':
            if 'set' in words[-4:-1]:
                return -0.4 if before == 'set' and words[-3] == 'a' else -1.15
            if before in {'list', 'sum', 'mean'}:
                return -0.6
            return -0.3 if before == 'first' else -0.05
    elif token == 'able':
        if previous in {'flow', 'fold'}:
            return -1.5
        if previous in ABLE_STEMS:
            return -0.75
    elif word in {'holder', 'holders'}:
        if previous in {'stock', 'card', 'policy'}:
            return -1.7
        if previous in {'share', 'bond', 'ticket', 'copyright'}:
            return -0.7
        if previous in {'house', 'lease'}:
            return -0.4
        if token == 'Holder' and raw:
            return -0.5
    elif token == 'ERS' and previous.endswith('stockhold'):
        return -1.1
    elif token == 'symbol' and old.endswith('\\bold'):
        return -1.5
    elif token == 'gl' and old.endswith(('\\big', '\\Big')):
        return -1.0
    elif word == 'possible' and previous == 'if':
        return -0.8 if raw == 'If' else -0.1
    elif word == 'example' and previous == 'this':
        return 0.4 if before == 'in' else 0.08
    elif word == 'module' and previous in {'this', 'load', 'get'}:
        return -0.65
    elif word == 'flow' and previous == 'data':
        return -0.6
    elif word == 'box' and previous in {'dialog', 'message'}:
        return -0.6
    return None


def background(token, first):
    """A coarse token-class correction, fitted separately from the phrases."""
    word = token.strip()
    value = -0.0017
    if word.lower() == 'the':
        value += 0.0076
    if token.isspace():
        value -= 0.0048
    if first:
        value += 0.146
        categories = wordnet.categories(word.lower())
        if 'noun.body' in categories:
            value -= 0.201
        if 'verb.stative' in categories:
            value -= 0.150
        if regex.search(r'\p{Script=Cyrillic}', token):
            value -= 0.256
        if regex.search(r'\p{Script=Han}', token):
            value -= 0.207
        if word.isupper():
            value += 0.167
        if word.istitle():
            value -= 0.140
        if token.startswith(' '):
            value -= 0.084
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = activation(old, token)
    if value is None:
        value = background(token, first)
    return (doc, (old + token)[-100:]), value

programs.haiku:
"""Activation of layers.1.mlp.down_proj:3925, predicted from the text around each token.

The component is mostly quiet; it has a few strong, readable triggers:
  * the dot-leader token "··" (a run of middle dots, as in a table of contents): strongly negative;
  * "all" after a search verb ("find all", "Find all", "xml.find_all"): strongly negative;
  * "symbol" after "\\bold" (LaTeX bold symbol) and "holders" (stockholders, cardholders): negative;
  * "of" after "group" or "family" ("a group of", "a family of"): positive.
Everything else is predicted as 0.
"""
READS = ()

SEARCH_WORDS = {"find", "Find", "finds", "Determine", "determine"}

def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2].strip() if len(s) > 1 else ""
    recent = [x.strip() for x in s[-6:-1]]
    value = 0.0
    if cur == "··":
        value = -1.2
    elif cur in ("_all", "all") and (prev in SEARCH_WORDS or prev.endswith("find")):
        value = -1.4
    elif cur == "symbol" and "\\bold" in "".join(s[-3:-1]):
        value = -1.7
    elif cur in ("holders", "Holders", "holder", "Holder"):
        value = -1.2
    elif cur == " of" and prev in ("group", "family"):
        value = 0.4
    return carry, float(value)

programs.sol:
"""A spelling-sensitive literature feature, not a general topic classifier.

The liter-/litter- family is negative, with stronger responses when a token
completes 'literature', and after 'the'.  Literal and literacy are weaker.
Also recognize linter, dictionary translations of literature, and a positive
-lyn fragment in names.  Track the latest word across token boundaries and
reset at document edges.
"""
import re
from functools import lru_cache
from anyascii import anyascii
import cedict

READS = ()
LETTERS = re.compile('[a-z]+')
LITERATURE_STEM = re.compile(r'l(?:it|itt|ett)erat')
LITERATURE = re.compile(r'l(?:it|itt|ett)erat(?:ur|$)')
LITERARY = re.compile(r'li(?:t|tt)erar')


@lru_cache(maxsize=8192)
def literature_term(term):
    return 'literature' in cedict.glosses(term) or term in ('문학', '문헌')


def word_response(previous, raw_text):
    text = anyascii(raw_text).lower()
    matches = list(LETTERS.finditer(previous + text))
    if not matches:
        return '', 0.0
    match = matches[-1]
    word = match.group()
    tail = word[-40:] if (previous + text)[-1:].isalpha() else ''
    if match.end() <= len(previous):
        return tail, 0.0
    before = previous[match.start():] if match.start() < len(previous) else ''
    parts = LETTERS.findall(text)
    own = parts[-1] if parts else ''
    value = 0.0
    if 'literal' in word:
        value = 1.1 if before.endswith('liter') and own == 'ally' else -0.13
    elif LITERATURE.search(word) and not LITERATURE_STEM.search(before):
        if before:
            complete = re.search(r'(?:li(?:t|tt)eratures?|letteratura)$', word)
            value = -11.5 if complete else -6.5
        else:
            value = -8.9 if previous == 'the' else -7.2
    elif LITERARY.search(word) and not LITERARY.search(before):
        value = -8.3 if before else -6.6
    elif 'splitter' in word:
        pass  # 'splitter' is not the litter/glitter spelling family.
    elif 'litter' in word and 'litter' not in before:
        value = -6.8 if before else -5.5
    # Latin inflections of littera, and English endings on glitter.
