    ({'时', '時', '时候', '時候'}, (0.35, 1.55, 1.80)),
    ({'的时候', '的時候'}, (1.30, 2.00, 2.00)),
    ({'阶段', '階段', '期间', '期間'}, (0.35, 0.60, 1.20)),
    ({'过程', '過程'}, (0.85, 0.85, 1.10)),
    ({'过程中', '過程中'}, (2.60, 2.80, 2.80)),
    ({'的过程中', '的過程中'}, (1.60, 1.60, 1.60)),
)
LAST_WORD = re.compile(r"([A-Za-z]+(?:[-'][A-Za-z]+)?)$")
KANA = regex.compile(r'\p{Script=Hiragana}|\p{Script=Katakana}')
MODALS = {'can', 'could', 'may', 'might', 'must', 'shall', 'should',
          'will', 'would'}


@lru_cache(maxsize=20000)
def english_head(word):
    forms = set(wordnet.base_forms(word, 'noun')) | {word}
    for heads, scores in ENGLISH:
        if forms & heads:
            return heads, scores
    return None


@lru_cache(maxsize=20000)
def modifier(word):
    if word in MODALS:
        return 0
    if word.endswith('ing') and len(word) > 4:
        return 2
    if wordnet.categories(word, 'noun') & {
        'noun.act', 'noun.event', 'noun.process'
    }:
        return 2
    return int('noun' in wordnet.parts_of_speech(word))


@lru_cache(maxsize=20000)
def chinese_activity(ending):
    # An infinitive gloss or activity-noun reading is an action cue.
    for width in (4, 3, 2):
        word = ending[-width:]
        if len(word) != width:
            continue
        for gloss in cedict.glosses(word):
            if gloss.startswith('to '):
                return True
            if gloss.isalpha() and modifier(gloss.lower()) == 2:
                return True
    return False


def predict(token, text):
    word = token.strip().lower()
    if token.startswith(' ') and word.isascii() and word.isalpha():
        head = english_head(word)
        if head:
            match = LAST_WORD.search(text)
            previous = match.group().lower() if match else ''
            heads, scores = head
            verb_cue = MODALS | {
                'to', 'please', 'i', 'you', 'we', 'they', 'he', 'she', 'it'
            }
            if 'process' in heads and previous in verb_cue:
                return 0.0  # 'to process' is a verb, not a process noun.
            kind = modifier(previous)
            # Phase heads require an overt activity-noun suffix.
            if 'phase' in heads and not previous.endswith(
                ('ing', 'tion', 'ment', 'sion')
            ):
                kind = 0
            return scores[kind]
    for heads, scores in CHINESE:
        if word in heads:
            if KANA.search(text[-40:]):
                return 0.0
            context = (
                2 if chinese_activity(text[-4:]) else int('在' in text[-15:])
            )
            return scores[context]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, text)
    return (doc, (text + token)[-120:]), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:3933 -- a "process / occasion" detector.

What it does: this component fires on the word that closes a setting phrase naming a
procedure, occasion or moment, such as "the data collection process", "at the hearing",
"the ceremony", or the Chinese time words 时 / 的时候 / 过程中 / 会上 / 后 / 前 ("when",
"during", "on", "after", "before"). It is near zero on the same words used as verbs
("we need to process them"), and it also fires weakly on long random-looking strings
(base64-like hashes and IDs). It is pushed negative on the first token of a document
and on the repeated middle-dot token "··".

The program is a lookup on the current token plus a little context: the previous word
(to rule out verb uses) and whether the current token sits in a run of mixed-case
letters and digits. Its values are rounded from a least-squares fit on training text.
"""

import re

READS = ()

# Procedure / occasion nouns, with rough typical activation.
PROCESS_NOUN = {" process": 0.9}
PROCEDURE_NOUNS = {
    " processes": 0.6, " procedure": 0.4, " procedures": 0.4, " hearing": 0.6,
    " ceremony": 0.8, " session": 0.4, " sessions": 0.4, " meeting": 0.3, " operation": 0.3,
    " operations": 0.3, " stage": 0.4, " stages": 0.4, " committee": 0.4, " Committee": 0.5,
    " Guide": 0.5, " guide": 0.3, " purposes": 0.5, " fee": 0.3, " fees": 0.3, " Fee": 0.5,
}
# Chinese time / occasion words: 时 "when", 后 "after", 前 "before", 上 "on", 中 "during".
CHINESE_WHEN = {"时": 0.9, "時": 0.7, "时候": 0.8}
CHINESE_EVENT = {"的时候": 1.7, "过程中": 2.0, "過程中": 2.0, "过程": 0.9, "阶段": 0.6, "会上": 1.5}
CHINESE_AFTER = {"后": 0.4, "前": 0.3, "上": 0.3, "後": 0.4, "上的": 0.3}

# Verbs or pronouns right before a word mean it is used as a verb, not a noun.
VERB_CONTEXT = {"to", "can", "we", "We", "must", "will", "I", "you", "they", "and", "may",
                "should", "need", "would", "could"}

RANDOM_STRING_VALUE = 0.2
DOCUMENT_START_VALUE = -0.07
REPEATED_DOT_VALUE = -0.6


def in_random_string(strings):
    """True if the last token ends a run of at least 16 letters/digits (no spaces or
    punctuation) that mixes upper case, lower case and digits, like a base64 hash."""
    run = ""
    for s in reversed(strings):
        if not re.fullmatch(r"[A-Za-z0-9+/=]+", s):
            break
        run = s + run
        if len(run) > 40:
            break
    return (
        len(run) >= 16
        and bool(re.search(r"[0-9]", run) and re.search(r"[a-z]", run) and re.search(r"[A-Z]", run))
    )


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOCUMENT_START_VALUE
    if tok == "··":
        return carry, REPEATED_DOT_VALUE
    for table in (PROCESS_NOUN, PROCEDURE_NOUNS):
        if tok in table:
            return carry, 0.0 if prev in VERB_CONTEXT else table[tok]
    for table in (CHINESE_WHEN, CHINESE_EVENT, CHINESE_AFTER):
        if tok in table:
            return carry, table[tok]
    if in_random_string(prefix.token_strings):
        return carry, RANDOM_STRING_VALUE
    return carry, 0.0

programs.sol:
"""Predict local cues for a name or identifier slot.

Rules cover naming words, declaration keywords, property/parameter annotations,
and quoted names in fields, API calls and option definitions.  Further cues
are serialization tags and TeX command definitions.  The rules use at most
200 preceding characters, reset between documents, and default to zero.
They approximate these constructions without parsing the language.
"""
import re

READS = ()
DECLARATIONS = {'public': .9, 'private': .45, 'protected': .8,
                'pub': 1.3, 'fn': .6, 'def': .15, 'let': .25,
                'func': .2, 'inline': .25, 'theorem': .3}
NAME_FIELDS = {'name', 'names', 'rename'}
IDENTIFIER_FIELDS = {'id', 'key', 'label', 'alias', 'identifier', 'tag',
                     'title', 'filename', 'property', 'field'}


def boundary(token, tail):
    word = token.lstrip(' \t')  # Preserve newlines: a closing quote is not an opener.
    if not word:
        return 0.
    if word in {'name', 'Name', 'NAME', '_name', '.name'}:
        if re.search(r'<param\s*$', tail):
            return 9.
        return .9 if token == 'name' else .4
    if word in {'nameof', '(nameof', '(rename'}:
        return 2.5
    if word in {'名称', '名稱', '稱'}:
        return .8
    if word in {'名为', '名為', '以下简称', '以下簡稱'}:
        return 1.8
    if word in DECLARATIONS:
        tail = re.sub(r'\\+[nrt]', '\n', tail)
        if word == 'def' and re.search(r'@property[^\n]*\n[^\n]*$', tail):
            return 10.
        if word == 'def' and re.search(r'@(?:classmethod|staticmethod)', tail[-80:]):
            return 2.
        if not tail.strip() or re.search(r'[\n\t{};] *$', tail) or tail.endswith('   '):
            return DECLARATIONS[word]
    if word in {'mut', 'Some'} and re.search(r'\blet\s*$', tail):
        return 5.1 if word == 'mut' else 6.
    if word == 'param' and tail.rstrip().endswith('@'):
        return .48
    if word in {'#include', '#pragma'}:
        return 1.3 if not tail or tail.endswith('<|endoftext|>') else .2
    if word.startswith('{') and re.search(r'\\(?:re)?newcommand\*?\s*$', tail):
        return 5.2
    if word == '[' and re.search(r'@param\s*\{[^{}]*\}\s*$', tail):
        return 6.
    if word == '}' and re.search(r'@param\s*\{[^{}]*$', tail):
        return 3.8
    if word == '{' and re.search(r'@param\s*$', tail):
        return -1.7
    if word == '$':
        annotation = re.search(r'@(property|param|var)\s+([\w\\|?]+)\s*$', tail)
        if annotation:
            string_property = (annotation[1] == 'property' and
                               annotation[2] == 'string')
            return 8. if string_property else 3.5
        if re.search(r'\bmy\s*$', tail):
            return 2.5
    if not any(c in word for c in "\"':`="):
        return 0.

    # Decode textual escapes only for recognizing local syntax, not whole strings.
    context = re.sub(r'\\+[nrt]', ' ', tail).replace('\\', '')
    match = re.search(r'([A-Za-z_][A-Za-z_0-9]*)([^A-Za-z_0-9]*)$', context)
    previous = match[1].lower() if match else ''
    ending = match[2].strip() if match else ''
    name = previous in NAME_FIELDS
    compound_name = previous.endswith('name') and not name
    identifier = previous in IDENTIFIER_FIELDS or compound_name
    clean = word.replace('\\', '')
    if clean in {':', '":', "':"} and ending in {'', '"', "'"}:
        return (1.7 if clean == ':' else 1.2) if name else (.5 if identifier else 0.)
    if clean == '=' and previous.startswith('rename'):
        return 5.4
    if clean == '`':
        if previous in {'table', 'key', 'index', 'column'}:
            return 4.
        return 2.3 if previous in {'named', 'name', 'called'} else 0.

    opening = re.fullmatch(r"([(:=\[]?)[\"'](--?|/|__)?", clean)
    if not opening:
        return 0.
    punctuation, suffix = opening.groups()
    quote = '"' if '"' in clean else "'"
    escaped = '\\' in word
    flag_call = re.search(
        r'(?:add_argument|[.]option|[.]flag)\s*\([^()]*$',
        (context + punctuation)[-190:])
    if suffix and suffix.startswith('-') and flag_call:
        return 8.5 if suffix == '--' else 6.
    if punctuation == ':' and previous in {'json', 'xml', 'yaml'}:
        return 4.8
    field_syntax = ending in {'', '"', "'", ':', '":', "':", '='}
    assigned_field = field_syntax and ending.endswith((':', '='))
    if punctuation in {'=', ':'} or assigned_field:
        if previous == 'dest':
            return 12. if clean == "='" else 4.
        if name:
            return (7.2 if quote == '"' else 4.) * (.75 if escaped else 1.)
        if previous == 'id':
            return 4.4 if punctuation == '=' else 2.
        if identifier:
            return 5.5 if previous == 'property' else 2.2
    if punctuation == '(':
        if re.search(r'print|log|error|warn|require', previous):
            return 0.
        if re.search(r'param|variable|attribute', previous):
            return 4.5
        if name or identifier or re.search(
                r'name|register|set_var|option|argument', previous):
            return 2.8
        if re.search(
                r'get|set|put|add|create|describe|config|image|^on$|^it$', previous):
            return 2.
        return .6
    if punctuation == '[':
        return .9
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = boundary(token, tail)
    return (doc, (tail + token)[-200:]), float(value)

"""A code-name prefix feature, distinguished from the same words in prose.

Boolean predicate prefixes (especially 'is') and event-handler 'on' are
negative. Member access, declarations, indentation, quotes, and camel case
supply evidence that a token begins a name. Bounds and operation prefixes
and private-name underscores have smaller negative values. Length members and
a few small-number contexts have positive values. This is a lexical approximation: it does
not infer the meaning of arbitrary identifiers.
"""
import re

READS = ()
PREDICATES = {
    'is': -4.7,
    'has': -3.6,
    'can': -3.1,
    'should': -2.4,
    'on': -4.3,
}
OPERATIONS = {'handle', 'allow', 'use', 'set', 'skip', 'enable', 'disable'}
PREFIXES = set(PREDICATES) | OPERATIONS | {'min', 'max'}
DECLARATION = re.compile(
    r'\b(?:bool|boolean|const|let|var|def|fn|void|pub|int|except)\s*$'
    r'|(?:^|[;\n{}])\s*(?:export\s+)?(?:function|private|public)\s*$'
    r'|\b(?:public|private|async|export)\s+function\s*$'
    r'|\{boolean\}\s*$'
)
CODE = re.compile(r'[{};=]|\b(?:def|return|if|const|let|var|bool|boolean)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('._/(').lower()
    value = 0.0

    if word in PREFIXES:
        # Code is often embedded in JSON strings with escaped indentation.
        context = before.replace('\\n', '\n').replace('\\t', '\t')
        previous = context.rstrip()
        last = previous[-1:] or ' '
        attached = (bool(context) and not context[-1].isspace()
                    and not token[:1].isspace())
        code = bool(CODE.search(context))
        # How strongly the local syntax suggests an identifier rather than prose.
        strength = 0.0
        if (text.startswith('.') or (attached and last == '.')
                or previous.endswith(('->', '::'))):
            strength = 1.0
        elif text.startswith(('_', '/')) or (attached and last in '_$'):
            strength = 0.8
        elif DECLARATION.search(context):
            strength = 1.1
        elif context.endswith(('  ', '\t')) and code:
            strength = 0.95
        elif attached and last in '\"\'`':
            strength = 0.5
        elif previous.endswith('&&') or previous.endswith(' ||'):
            strength = 1.0
        elif code and last in ',={:':
            strength = 0.85 if word in {'is', 'has'} else 0.6
        elif re.search(r'\b(?:if(?: not)?|return)\s*$', previous):
            strength = 0.85
        elif text.startswith('('):
            strength = 0.75 if code else 0.3
        elif code and previous.endswith('new'):
            strength = 1.0
        elif attached and last in '([!,{$=:':
            strength = 0.75 if code else 0.3
        elif attached and text[:1].isupper() and last.islower():
            strength = 0.3 if word == 'on' else 0.75

        if word in PREDICATES:
            value = PREDICATES[word] * strength
            if text.isupper():  # SQL operators and acronyms are not camel-case names.
                value *= 0.15
        elif word in {'min', 'max'}:
            value = -(1.5 if word == 'max' else 1.0) * strength
            if not strength and code:
                value = -0.6 if word == 'max' else -0.3
        elif word in OPERATIONS:
            value = -0.9 * strength
    elif text in {'__', '._', '.__'} and (token[:1].isspace() or text[0] == '.'):
        value = -0.7
    elif text.lower() == '.length' or (text == 'length' and before.endswith('.')):
        value = 0.8
    elif token in {'0', '1', '2'} and not before[-1:].isdigit():
        previous = before.rstrip()
        if before.endswith('exit code '):
            value = 1.2
        elif before.endswith('__'):
            value = 0.75
        elif previous.endswith('['):
            value = 0.25 if token == '0' else 0.13
        elif previous.endswith(('=', '(', '<', '>')):
            value = 0.15 if token == '0' else 0.05
    return (doc, (before + token)[-160:]), float(value)

"""A spelling-and-expression detector, not a general sentiment classifier.

Negative responses concentrate on good/God/gut, their split spellings, and
expressions of relief or gratitude. Short h + vowel + d spellings instead
receive positive responses (especially hood/HUD). Most other text is quiet.
Greek-delta and document-format rules cover a few additional responses.
The rules deliberately omit the component's many weak lexical biases.
"""
import re
import regex
from anyascii import anyascii

READS = ()
ALPHABETIC = regex.compile(
    r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{Arabic}\p{P}\p{N}\s]*'
)


def roman(text):
    # Do not confuse romanized Chinese syllables with Latin spelling pieces.
    return anyascii(text).lower().rstrip() if ALPHABETIC.fullmatch(text) else ''


def response(token, previous, tail, first):
    s, p = token.strip().lower(), previous.strip().lower()
    a, b = roman(s), roman(previous)
    joined = not token[:1].isspace() and s.isalpha()
    capital = token.strip()[:1].isupper()
    value = 0.002

    # Complete words and exclamations involving goodness or a deity.
    if s == 'good':
        value = -0.65 if capital else -0.25
    elif s == 'god':
        value = -2.0 if capital else -3.0
        if not token[:1].isspace():
            value -= 0.8
        if re.search(r'\b(oh|my)[ .,!?]*$', tail.lower()):
            value -= 2.8
    elif s in ('gods', 'gott', 'gottes'):
        value = -2.0
    elif s in ('goddess', 'goddesses'):
        value = -0.6
    elif s in ('gut', 'guts', 'goed', 'gode'):
        value = -3.9
    elif s in ('gute', 'guten', 'guter', 'gutes'):
        value = -1.2
    elif s == 'glad':
        value = -0.7 if capital else -2.8
    elif s == 'goodness':
        value = -15.5 if p == 'thank' else -5.5
    elif s in ('grateful', 'gratefully'):
        value = -0.85
    elif s in ('thankful', 'thankfully'):
        value = -1.2
    elif s in ('fortunately', 'luckily'):
        value = -1.4
    elif s in ('heaven', 'heavens', 'heavenly'):
        value = -4.0 if p == 'for' else -1.5
    elif s in ('luck', 'lucky'):
        value = -2.1 if p == 'good' else -0.3
    elif s in ('还好', '幸好', '幸亏', '多亏'):
        value = -5.6
    elif s in ('上帝', '天哪', '天啊', '老天'):
        value = -2.2
    elif s == '幸':
        value = -0.9

    # Familiar two-token expressions; no look-ahead is used.
    if s in ('ahead', '-ahead') and p in ('go', 'goes', 'going'):
        value = -5.2
    elif s == 'for' and p == 'thanks':
        value = -3.0
    elif s == 'lot' and tail.lower().endswith('thanks a'):
        value = -1.6
    elif s in ('thing', 'things') and p in ('good', 'bad'):
        value = -4.5 if p == 'good' else -2.0

    # A word split just before a suffix can respond much more strongly.
    if joined and p.endswith('good') and s in ('ness', 'ly', 's', 'es'):
        value = -11.5 if s == 'ness' else -6.5
    elif joined and p.endswith(('god', 'glad')) and s in ('ly', 'd', 'ness'):
        value = -3.8
    elif joined and s == 'fully' and p == 'thank':
        value = -7.0

    # Short vowel/dental-consonant fragments after g versus h. Romanization
    # also covers Cyrillic год and related spellings, without a token-ID table.
    if joined and len(a) <= 4:
        if b.endswith(('g', 'gl')):
            if a.startswith('od'):
                value = -4.6
            elif a in ('ad', 'add', 'ads', 'ud'):
                value = -2.8
            elif a == 'ada':
                value = -1.3
            elif a in ('ut', 'utan') and s.isascii():
                value = -5.5 if b.endswith('g') else -2.6
            elif a == 'lad':
                value = -3.7
            elif a == 'osh':
                value = -10.0
        if b.endswith('gh') and a == 'osh':
            value = -7.0
        if b.endswith('h'):
            if re.fullmatch(r'(?:[iu]d|ood)(?:[ds]|en)?', a):
                value = 3.6 if not b.endswith(('ch', 'th', 'gh')) else 1.0
            elif a in ('od', 'ad', 'aud'):
                value = 1.5 if not b.endswith(('ch', 'th', 'sh')) else 0.6
            elif a == 'ed' and not b.endswith(('ch', 'th', 'sh', 'gh')):
                value = 1.2
            elif a in ('df', 'dd'):
                value = 5.7
        if a.startswith('d') and b.endswith('y'):
            value = 0.8

    # Whole-token counterparts of some positive spelling fragments.
    if a in ('hood', 'hoods'):
        value = 1.3 if joined else 5.8
    elif a == 'hud':
        value = 4.2
    elif s == 'hod':
        value = 2.6 if capital else 0.1
    elif a == 'hydro':
        value = 0.9
    elif joined and a.startswith('ydro') and b.endswith('h'):
        value = 2.0
    elif s == 'δ' and joined and regex.search(r'\p{Greek}$', previous):
        value = 2.3 if b.endswith(('ei', 'u')) else 0.8

    # Small document-format responses visible even without linguistic context.
    if first and s == '#':
        value = 2.18
    elif first and s.startswith('/*'):
        value = 2.66
    elif first and s in ('package', 'import'):
        value = 1.98
    elif len(s) >= 2 and set(s) == {'·'}:
        value = -0.51
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, tail, first)
    return (doc, token, (tail + token)[-64:]), float(value)

"""Sparse word and layout responses, with zero for ordinary text.

The strongest word cue is Chinese 'service', weaker in computing contexts.
A few Chinese assistance and joy/sweetness words also respond negatively.
Nonbreaking-space responses fade with repetition and are stronger in Han
text. Line breaks after Han text respond positively, especially near the
beginning of a document.
This deliberately leaves other lexical and contextual variation unexplained.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
COMPUTING = ('软件', '軟件', '数据', '數據', '微服务', '微服務',
             'IT', 'OCLC', 'RealPlayer', 'PDF')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, 0, False, '', True)
    _, spaces_seen, position, previous_han, recent, leading = carry
    text = prefix.token_strings[-1]
    n_spaces = text.count('\u00a0')
    value = 0.0

    if n_spaces:
        if '\n' in text:
            value = 0.04 - 0.035 / (1 + spaces_seen) ** 0.75
        elif text == '\u00a0':
            value = 0.02 - 0.39 / (1 + spaces_seen)
        elif text == '\u00a0' * n_spaces:
            if n_spaces <= 4:
                value = -0.27 - 1.36 / (1 + spaces_seen) ** 0.75
            else:
                value = -0.02 - 1.03 / (1 + spaces_seen) ** 0.5
        else:  # alternating ordinary and nonbreaking spaces
            value = -0.48 / (1 + spaces_seen) ** 0.5
        if leading and position < 4:
            value = -2.0
        if '\n' not in text and HAN.search(recent[-32:]):
            value -= 3.0 / (1 + spaces_seen) ** 0.5
        spaces_seen += 1
    elif text in ('服务', '服務'):
        if recent.endswith('微'):
            value = -0.25  # microservices, rather than personal/public service
        elif any(word in recent for word in COMPUTING):
            value = -1.8
        else:
            value = -2.8
    elif text in ('服务业', '服務業'):  # service industry
        value = -2.3
    elif text[:1] in '和的与與及' and text[1:] in ('服务', '服務'):
        value = -2.7 if text.startswith('的') else -1.8
    elif text in ('志愿者', '志愿服务'):  # volunteer; volunteering
        value = -2.0
    elif text.endswith(('服务', '服務')):
        value = -0.6
    elif text in ('客服', '福利'):  # customer service; welfare
        value = -0.8
    elif text in ('快乐', '快樂'):
        value = -1.6 if text == '快乐' else -0.5
    elif text in ('悦', '悅'):
        value = -1.4
    elif text in ('乐', '樂', '楽'):
        value = -0.4 if text == '乐' else -0.1
    elif text == '甜':  # sweet
        value = -0.8
    elif text in (' service', ' services'):
        value = 0.13
    elif '\n' in text and previous_han:
        if text == '\n':
            value = 0.025 + 190 / (position + 32) ** 1.5
        else:
            value = -0.02 + 10.6 / (position + 32)

    return (document, spaces_seen, position + 1, bool(HAN.search(text)),
            (recent + text)[-256:], leading and text.isspace()), value

"""A coarse onset pulse, with a few sharp spelling-specific exceptions.

At document onset, most tokens get a negative pulse, weaker for lower-case
ASCII text. Away from onset the prediction is zero, except for Ur + text.
The observed large positive exceptions are the initial `_base` fragment,
and the second tokens of initial Hy + dro and { + [. These are distinct
surface constructions, not one proposed semantic category. Most ordinary
word-specific variation is deliberately left unexplained.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        offset, previous = 0, ''
    else:
        _, offset, previous = carry
        offset += 1

    value = 0.0
    if offset == 0:
        text = token.strip()
        if text.isascii() and text.islower():
            value = -0.04
        elif len(text) <= 1:
            value = -0.25
        else:
            value = -0.14
        if token == '<|endoftext|>':
            value = -2.162
        elif token == '{':
            value = -0.47
        elif token == 'Hy':
            value = 0.38
        elif token == '_base':
            value = 1.62
    elif offset == 1:
        if previous == '{' and token == '[':
            value = 1.561
        elif previous == 'Hy' and token == 'dro':
            value = 2.853
    if previous == ' Ur' and token == 'text':
        value = -0.78
    return (doc, offset, token), value

"""Partial approximation of large responses with little preceding context.

Use token classes and individual digit values at a document/row opening;
keep that estimate while the same opening token repeats.  Distinguish code
openings, middle dots, shell punctuation, articles, pronouns and Han text.
Recognize a Home breadcrumb separator, a Title: header and a Java package
opening.  Elsewhere predict nearly zero, with small corrections for
nonbreaking spaces and closing conversation-control tags.

This leaves most small, word-specific activation differences unexplained.
