READS = ()
CODE_OPENINGS = frozenset(('using', 'import', 'from', 'const', 'function'))
PRONOUNS = frozenset(('I', 'You', 'He', 'She', 'We', 'They'))
DIGIT_OPENING = (0.43, 0.47, 0.16, 0.09, 0.57,
