def opening(s):
    word = s.strip()
    if word == '>&':
        return 1.74
    if word == '>':
        return 0.75
    if s == '\u00a0':
        return 1.15
    if word in CODE_OPENINGS:
        return -0.95
    if s == '<|im_start|>':
        return 0.065
    if s == '<|endoftext|>':
        return 1.0
    if len(s) == 1 and s in '0123456789':
        return DIGIT_OPENING[int(s)]
    if s and set(s) <= {'·'}:
        return 1.47
    if word in PRONOUNS:
        return 0.6
    if word.lower() == 'the':
        return 0.08 if word == s else -0.3
    if word.lower() in ('a', 'an'):
        return 0.37
    if len(word) == 1 and word.isascii() and word.isupper():
        return 0.55
    if s.startswith(('#', '//', '/*')):
        return -0.35
    if regex.search(r'\p{Script=Han}', s):
        return 0.055
    return 0.21


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, s, True, 0, s)
    _, first, uniform, position, previous = carry
    uniform = uniform and s == first
    value = 0.001
    if s and set(s) == {'\u00a0'}:
        value = -0.06
    elif s in ('</tool_call>', '</tool_response>', '</think>'):
        value = -0.065
    if uniform:
        value = opening(s)
    elif s.strip() == '>' and previous.strip().lower() == 'home':
        value = 0.77
    elif position == 1 and previous == 'Title' and s == ':':
        value = -3.964
    elif position == 1 and previous == 'package' and s == ' com':
        value = -1.546
    return (doc, first, uniform, position + 1, s), value

"""Sparse local cues, not a single semantic category.

Positive: 越 and a few related Chinese spellings; Yue, Viet and Vue;
short vowel continuations after v. Negative: experiential 过/過 after
a verb, strengthened by earlier 'never/previously' markers. Japanese
越 compounds and French vue receive much smaller responses. A short
byte buffer also recognizes pieces of the Chinese spellings.
"""
import unicodedata
from functools import lru_cache
import cedict
import regex

READS = ()
NON_ASPECT = ('不', '通', '超', '透', '经', '經', '错', '錯', '难', '難', '太')
EVENT_VERBS = ('发生', '發生', '引起', '出现', '出現', '接触', '接觸', '遇到', '收到')
NEVER = ('从来没有', '從來沒有', '从未', '從未')
EARLIER = ('曾', '以前', '之前', '没', '沒有', '没有', '沒')


@lru_cache(maxsize=8192)
def is_verb(word):
    return any(g.startswith('to ') for g in cedict.glosses(word))


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c)).lower()


def spelling(text, previous, recent):
    low, prev = unaccent(text), unaccent(previous)
    if text == '越':
        return 0.8 if regex.search(r'\p{Hiragana}', previous) else 4.1
    if text in ('悦', '悅', '粤', '粵'):
        return 3.3
    if text.startswith(('越大', '越高', '越低', '越多', '越來越')):
        return 3.2
    if text.startswith('越来越') or text in ('就越', '越是', '越南'):
        return 1.8
    if text == '愈':
        return 0.7
    if '\ufffd' in text:
        for char, value in (('越', 4.0), ('粤', 1.8)):
            encoded = char.encode('utf-8')
            if recent.endswith(encoded):
                return 5.0 if char == '越' else 2.5
            if recent.endswith(encoded[:2]):
                return value
    if low.strip(' ./') == 'vue':
        if text.startswith(' '):
            return 4.5 if previous.rstrip().endswith('=') else (
                3.2 if text.strip() == 'Vue' else 0.0)
        if text == 'vue' and previous.isalpha():  # French compounds
            return 0.3
        return 6.4 if "'" in previous or '"' in previous else 4.5
    if low.strip() == 'viet':
        return 4.5 if text.startswith(' V') else 2.0
    if low.strip() == 'yue':
        return 6.5
    if text.startswith((' ', '\n')):
        return 0.0
    if (prev + low).endswith('yuer'):
        return 3.3
    if (prev + low).endswith('yue'):
        return 6.5
    if prev.endswith('v'):
        if low == 'ue':
            return 0.8 if prev.endswith('rev') else (
                7.4 if prev.endswith('-v') else 4.2)
        if low == 'iet':
            return 3.0
        if low in ('ie', 'ict'):
            return 0.5
        if low in ('ite', 'itest') and prev.strip(' ./-') == 'v':
            return 1.5
    if prev.endswith('vi') and low in ('et', 'este'):
        return 6.0 if text[0] != low[0] else 1.6
    if prev.endswith(('vi', 'mi', 'vit')) and low == 'est':
        return 2.5
    if prev.endswith('w') and low == 'iet':
        return 2.0
    if previous.endswith(('в', 'В')) and text == 'ят':
        return 1.0
    if prev.endswith('y') and low == 'est':
        return 2.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, recent = ((), b'') if carry is None or carry[0] != doc else carry[1:]
    previous = history[-1] if history else ''
    text = prefix.token_strings[-1]
    recent = (recent + prefix.token_bytes[-1])[-8:]
    value = spelling(text, previous, recent)
    suffix = text in ('过', '過', '过的', '過的', '过了', '過了')
    if suffix or text.endswith(('过', '過')):
        base = previous if suffix else text[:-1]
        if base.endswith(NON_ASPECT):
            value = 0.0
        else:
            context = ''.join(history[-4:])
            verb = is_verb(base) or (base[:1] in '我你他她'
                                     and is_verb(base[1:]))
            value = -2.5 if verb else -0.6
            if base.endswith(EVENT_VERBS):
                value = -6.5
            if any(marker in context for marker in NEVER):
                value = -10.0 if text in ('过', '過') else -5.0
            elif any(marker in context for marker in EARLIER):
                value -= 1.6
            if text in ('过了', '過了'):
                value *= 0.3
    return (doc, (history + (text,))[-4:], recent), value

"""Approximate a separation signal, strongest on English ' from'.

Recent removal, departure, protection and difference words strengthen it;
ordinary provenance words weaken it. Related preposition phrases get smaller
signed responses. Also handle short f-u word splits and two opening headers.
All phrase state resets at a document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
SEPARATION = set('''remove removal separate separation detach disconnect withdraw
withdrawal depart departure retire retirement resign resignation expel evict eject
exclude exclusion preclude exempt exemption prohibit disqualify refrain deviate
deviation differ distinguish protect protection save shield rescue prevent liberate
escape flee shun discourage dissuade abstain avoid relieve eliminate subtract
alienate deport hide conceal delete erase wipe discharge diffuse immunity secure
absent absence freedom separable void reduce decrease lower slip restrict
steal cut keep'''.split())
DISTANCE = set('''different difference distance distant far isolate graduate'''.split())
PROVENANCE = set('''come derive originate result obtain make produce appear start range
receive get learn extract'''.split())

@lru_cache(maxsize=8192)
def forms(word):
    return frozenset((word, *wordnet.base_forms(word)))


def from_value(history):
    history = history.replace('\\n', ' ').replace('\\t', ' ')
    words = re.findall('[a-z]+', history.lower())[-12:]
    if 'from' in words:
        words = words[len(words) - words[::-1].index('from'):]
    recent = [forms(w) for w in reversed(words)]
    separation = min((i for i, f in enumerate(recent) if f & SEPARATION), default=99)
    distance = min((i for i, f in enumerate(recent) if f & DISTANCE), default=99)
    source = min((i for i, f in enumerate(recent) if f & PROVENANCE), default=99)
    if recent and 'return' in recent[0]:
        separation = 0
    # A newer provenance verb supersedes an unrelated, older separation cue.
    if source < separation:
        separation = 99
    if source < distance:
        distance = 99
    value = -1.18
    if separation < 4:
        value -= 3.96
    elif separation < 12:
        value -= 1.51
    if distance < 4:
        value -= 1.28
    last = words[-1] if words else ''
    if last in {'away', 'out', 'off', 'up', 'down'}:
        value -= 2.86
    if last in {'apart', 'aside'}:
        value -= 0.71
    if source < 2:
        value += 0.79
    if any('free' in f for f in recent[:3]):
        value -= 2.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    lower = token.lower()
    value = 0.0
    if lower == ' from':
        value = from_value(history)
    elif lower in {' of', ' to', ' with'}:
        words = re.findall('[a-z]+', history.lower())
        last = words[-1] if words else ''
        if lower == ' of':
            if last in {'out', 'outside', 'rid', 'devoid', 'free'}:
                value = -1.9
            elif last == 'short':
                value = -4.0
        elif lower == ' to':
            if last in {'out', 'down', 'off'}:
                value = 1.9
            elif forms(last) & {'reduce', 'decrease', 'lower'}:
                value = 1.5
        elif 'replace' in forms(last):
            value = 1.5
    # Short u-fragments completing f-prefixes, not -usion or inf-/conf-.
    short_u = lower.startswith('u') and (
        len(lower) <= 4 or lower[2:] in {'ed', 'es', 'ing'})
    if short_u:
        before = re.search('[a-z]+$', history.lower())
        before = before.group() if before else ''
        if before.endswith('f') and not before.endswith(('inf', 'conf')):
            value = -5.0
            if re.search('centrifug(e)?$', before + lower):
                value = -11.5
    if token == ':' and history.strip() in {'Title', '<|endoftext|>Title'}:
        value = -8.59
    if lower == ' com' and history.strip() == 'package':
        value = -4.88
    return (doc, (history + token)[-200:]), value

"""Coarse local word-boundary responses, not a complete activation model.

The main negative cues are comma + 'which', sentence-initial determiners,
short Cyrillic word beginnings, certain prefixes, and hyphenated fragments.
Lowercase e/i after punctuation are positive cues for e.g./i.e. beginnings.
A new document has a small negative baseline. Everything uses only the current
and preceding token; linguistic classes share average response strengths.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# Common one-letter Russian function words.
RUSSIAN_FUNCTION_WORDS = frozenset('а в и к о с у я'.split())
# Nasals, liquids, and stops, rather than fricatives/affricates.
RUSSIAN_STOPS_NASALS_LIQUIDS = frozenset('бгдклмнпрт')
RUSSIAN_VOWELS = frozenset('аеёиоуыэюя')
PREFIXES = {'pre': -0.55, 'inter': -0.59, 're': -0.24, 'sub': -0.12}


@lru_cache(maxsize=8192)
def frequency(word, language):
    return zipf_frequency(word.lower(), language)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    word = token.strip()
    lower = word.lower()
    before = previous.strip()
    space = token.startswith(' ')
    value = 0.0015

    if first:
        value = -0.14
    elif word in {'e', 'i'} and previous.endswith('('):
        value = 0.65
    elif word in {'e', 'i'} and space and previous.endswith(','):
        value = 0.48
    elif lower == 'which':
        value = -0.55 if previous.endswith((',', '(')) else 0.04
    elif space and lower in {'a', 'an'}:
        if word[0].isupper():
            if previous.endswith('.'):
                value = -0.51
            elif previous.endswith(':'):
                value = -0.30
            else:
                value = -0.02
        elif previous.endswith('.'):
            value = 0.07
        elif previous.endswith(','):
            value = -0.08
        else:
            value = -0.12 if len(before) > 5 else -0.025
    elif (space and previous.endswith('.')
          and word in {'This', 'The', 'Her', 'His', 'Our'}):
        value = -0.40 if word == 'This' else -0.08 if word == 'The' else -0.23
    elif space and lower in PREFIXES:
        value = PREFIXES[lower]
        if word.istitle():
            value = 0.0 if lower == 're' else value * 0.5
    elif word.startswith('-') and word[1:].isalpha() and len(word) <= 4:
        if before.isalpha() and len(before) >= 3 and frequency(before, 'en') >= 3:
            value = -0.40 if len(word) == 2 else -0.10 if len(word) == 3 else -0.025
        else:
            value = -0.035
    elif space and word.isalpha():
        script = unicodedata.name(word[0], '')
        if 'CYRILLIC' in script:
            if len(word) == 1:
                if not word.islower():
                    value = -0.18
                elif lower in RUSSIAN_FUNCTION_WORDS:
                    value = -0.025
                else:
                    if lower in RUSSIAN_STOPS_NASALS_LIQUIDS:
                        value = -0.80
                    else:
                        value = -0.20
            elif len(word) == 2 and word.islower() and frequency(word, 'ru') < 5.8:
                value = -0.40 if not any(c in RUSSIAN_VOWELS for c in word) else -0.13
        elif 'ARABIC' in script and len(word) == 1:
            value = -0.20
    elif len(word) == 1 and 'KATAKANA' in unicodedata.name(word, ''):
        value = -0.14
    elif word in {'は', 'も'}:
        value = 0.20

    return (doc, token), value

