"""Rule-based guess of layers.1.mlp.down_proj:3946 (layer 1 MLP, unit 3946).

The unit is quiet almost everywhere. It goes negative on word fragments that are not whole
words: a one- or two-letter Russian word-start piece, a single katakana syllable, a
hyphen-led piece; on clause-initial "which", "This", "A" after punctuation; on a run of
middle dots; and on the first token of a document. It goes positive on the "e" or "i" that
opens an "e.g." / "i.e." abbreviation after "(" or ",". Everything else predicts 0.
The program reads only the current token, the one before it, and the document start.
"""
READS = ()

# Short, common Russian words: a one- or two-letter Cyrillic token that is one of these
# is a whole word, not a fragment of a longer one.
COMMON_RU = set("и в с на к не от по у для из о что как или под я может за его это можно а но же до он она они мы вы то".split())
PUNCT = {",", ".", ")", "),", ":", ";"}
CLAUSE_START = {"which": -0.5, "This": -0.35, "A": -0.3, "An": -0.4}
VERBS_BEFORE_A = {"provides", "provide", "offers", "during", "through", "creating", "without", "that", "create", "like", "such", "over"}

def _cyrillic(word):
    return len(word) > 0 and all("Ѐ" <= c <= "ӿ" for c in word)

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    word = cur.strip()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.15   # first token of a document or row
    prev = prefix.token_strings[-2].strip()
    value = 0.0
    if cur[:1] == " " and _cyrillic(word) and word.islower() and len(word) <= 2 and word not in COMMON_RU:
        value = -0.6 if len(word) == 1 else -0.25   # Russian word-start fragment, e.g. " н" of " небольш..."
    elif word in ("e", "i") and prev in ("(", ","):
        value = 0.55                                  # "e.g." / "i.e." starts
    elif word == "··":
        value = -0.55                                 # run of middle dots
    elif word in CLAUSE_START and prev in PUNCT:
        value = CLAUSE_START[word]                    # clause-initial "which", "This", "A"
    elif word == "a" and prev in VERBS_BEFORE_A:
        value = -0.17
    elif len(word) == 1 and "\u30a0" <= word <= "\u30ff":
        value = -0.15                                 # a single katakana syllable: part of a loanword
    elif word.startswith("-") and word[1:].isalpha() and cur[:1] != " ":
        value = -0.07                                 # hyphen-led word piece
    return carry, float(value)

