"""Mostly an 'out / emerge' detector, with tokenization-sensitive strength.

Chinese 出 is strongly negative alone and as a resultative verb ending;
lexicalized words and Japanese inflections are weaker. Vietnamese ra and
Korean 출 also respond, with weaker values for creation/extraction/exposure.
English 'point out' is a smaller trigger. Otherwise document starts get a
small positive baseline (near zero for digits). Two incidental patterns are a
positive middle-dot pair and a negative document-opening 'Title:' colon.
Only short, document-local text and byte buffers are retained.
"""
import regex as re

READS = ()
VIETNAMESE = re.compile(r'[ăâđêôơư\u1ea0-\u1ef9]', re.I)
KANA = re.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
POINT = re.compile(r'\bpoint(?:s|ed|ing)?$', re.I)
# Presenting information versus physically producing or releasing something.
PRESENTING = {'提出', '推出', '指出', '列出', '播出'}
PRODUCING = {'做出', '作出', '发出', '拿出', '给出', '露出'}
EMERGING = {'流出', '走出', '说出', '传出', '打出'}
TECHNICAL = (
    '计算', '算', '预测', '识别', '識別', '提取', '导', '弹', '研制',
)


def chinese(s, context):
    if s == '出':
        if context.endswith(('輸', '输')):
            return 0.4
        if context.endswith(TECHNICAL):
            return -2.0
        return -3.0 if KANA.search(context[-12:]) else -4.4
    lexical = ('出版', '出租', '出售', '出会', '思い出')
    if s.startswith(lexical) or s == '派出所':
        return 0.0
    if s.startswith('出品'):
        return 1.3
    if s == '出口':
        return 0.6
    if '出来' in s or '出來' in s:
        if KANA.search(s) or KANA.search(context[-12:]):
            return -0.1
        if s.endswith('的') or s.startswith('不'):
            return -3.5
        return -3.1 if s.endswith('了') else -1.9
    if '不出' in s:
        return -6.2
    if s == '出了':
        return -4.8
    stem = s.removesuffix('的').removesuffix('了')
    if stem.startswith(('输', '輸')):
        return -0.6
    if stem in EMERGING:
        return -4.8
    if stem in PRODUCING:
        return -3.4
    if stem in PRESENTING:
        return -2.0
    if stem.endswith('出'):
        return -2.8
    if s == '出した':
        return -2.0
    if s.startswith(('出し', '出て', '出す')):
        return -1.1
    if s.startswith('出去'):
        return -1.5
    return -0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    context = previous.decode('utf-8', errors='ignore')
    s = prefix.token_strings[-1].strip()
