    value = (0.04 if s.isdigit() else 0.37) if not previous else 0.0
    if '出' in s:
        value = chinese(s, context)
    elif combined.endswith('出'.encode()):
        value = -5.8
    elif s == '출':
        if context.endswith('추'):  # 추출: extraction
            value = -1.7
        elif context.endswith('노'):  # 노출: exposure
            value = -0.9
        elif context.endswith('배'):  # 배출: discharge
            value = -1.2
        elif context.endswith('제'):  # 제출: submission
            value = -2.3
        else:
            value = -4.4
    elif combined.endswith('출'.encode()):
        value = -7.5
    elif s == '抜':
        value = -1.6
    elif s == 'ra' and raw.startswith(b' ') and VIETNAMESE.search(context):
        word = context.rstrip().rsplit(' ', 1)[-1].lower()
        if word in {'tạo', 'xảy'}:  # create / happen
            value = -2.6
        elif word in {'ngoài', 'diễn'}:  # besides / take place
            value = -3.6
        else:
            value = -5.4
    elif s.lower() == 'out':
        value = -0.75 if POINT.search(context.rstrip()) else -0.1
    elif s.lower() == 'outstanding':
        value = -0.5
    elif s.lower() == 'through':
        value = -0.22
    elif s == '··':
        value = 1.9
    elif s == ':' and context == 'Title':
        value = -4.15
    return (doc, combined[-192:]), value

"""Approximate a sparse spelling response, not a general meaning detector.
Pump spellings are strongly negative; French peu and Romance poco/po
spellings are positive. Joining word fragments handles split tokenizations.
Short Romance function-word context disambiguates po. Smaller rules cover
p-ul/p-om, PWM, Greek pi followed by omicron/iota, and middle-dot leaders.
"""
import re

READS = ()
ROMANCE = frozenset(
    'un une il le la les lo gli dei della che que non et du des '
    'au aux con nel di una uno nella delle'.split()
)


def response(s, previous, word, joined, recent, continues):
    piece = s.lower().strip()
    after_p = continues and previous.lower().endswith('p')
    if '泵' in s:
        return -11.3
    if re.search(r'pump(?:s|ed|ing|er)?$', joined):
        return -10.8 if piece.startswith('pump') else -13.2
    if piece in ('ump', 'umps') and not previous:
        return -13.2
    if piece.startswith('pwm') or (after_p and piece.startswith('wm')):
        return -2.7
    if after_p and re.fullmatch(r'ul(?:s|us|os|i|es)?', piece):
        return -3.3
    if after_p and piece.startswith('om'):
        return -1.9
    if piece in ('pul', 'puls', 'pom', 'pomp'):
        return -1.7
    if joined == 'peu':
        return 10.9 if continues and word else 5.4
    if joined in ('peut', 'peux'):
        return 5.9 if continues and word else 2.7
    if re.fullmatch(r'poc[oa]s?|poch[ie]|pouc[oa]s?|tampoco', joined):
        return 5.4 if continues and word else 4.5
    if piece == 'poc':
        return 2.9
    if piece == 'po' and (not continues or not word):
        if previous.lower().strip() == 'un':
            return 8.0
        words = set(re.findall(r'[a-z]+', recent.lower()))
        return 1.8 if words & ROMANCE else 0.1
    if previous.lower().strip() == 'po' and piece in ("'", '’'):
        return 8.0
    if piece == 'wenig':
        return 2.8
    if (previous.endswith(('π', 'Π'))
            and piece[:1] in ('ο', 'ό', 'ι', 'ί', 'Ο', 'Ι')):
        return 1.8
    if piece and len(piece) >= 2 and set(piece) == {'·'}:
        return 1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, recent = '', '', ''
    else:
        _, previous, word, recent = carry
    s = prefix.token_strings[-1]
    continues = bool(s and s[0].isalpha() and s == s.lstrip())
    joined = word + s.lower() if continues else s.lower().strip()
    joined = re.split(r'[^\wÀ-ÿ]+', joined)[-1]
    value = response(s, previous, word, joined, recent, continues)
    carry = (doc, s, joined[-30:], (recent + s)[-80:])
    return carry, value

"""Approximate a sparse negative response to scholarly/citation metadata.

Recognize publication resources, citation initials, dates, institution-list
separators, and a few document-layout boundaries. Ordinary text is near zero;
this deliberately does not model the component's many small lexical responses.
"""
import calendar
import re

READS = ()
SCHOLARLY_LABELS = (
    'Sci Advisor', 'Scientific Advisor', 'Institutional Repository',
    'BioMed Central', 'arXiv preprint', 'PubMed',
)
INSTITUTIONS = {
    'University', 'College', 'Colleges', 'Institute', 'Works',
    'Centre', 'Center', 'Headquarters', 'Corporation', 'Council',
}
# Do not mistake common qualifications and legal suffixes for authors' initials.
NOT_INITIALS = {
    'M.A', 'B.A', 'M.D', 'B.D', 'D.D', 'M.P', 'L.P',
    'F.R.S', 'D.C.L', 'K.C.B', 'K.C.S.I', 'C.B', 'K.G',
}
MONTH = '|'.join(calendar.month_abbr[1:])
CITATION_DATE = re.compile(r'\b\d{4} (?:' + MONTH + r')(?: \d{1,2})?$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = tail + token
    value = -0.0015

    if any(text.endswith(label) for label in SCHOLARLY_LABELS):
        value = -1.1
    elif re.search(r'\d+ CFR$', text):  # Code of Federal Regulations
        value = -0.9
    elif text.endswith('E-mail') and re.search(
        r'\b(?:University|College|Institute|Department|Laboratory)\b', tail
    ):
        value = -1.5
    elif token == 'Purpose' and tail.endswith('\n'):
        value = -1.1
    elif ';' in token and '\n' not in token and not any(
        ch.isalnum() for ch in token
    ):
        value = 0.06
        if token == '.;':
            initial = re.search(
                r'(?:, |\b[A-Z][a-z]+ )([A-Z](?:\. ?[A-Z])*)$', tail
            )
            if initial and initial[1] not in NOT_INITIALS:
                value = -1.6
        elif token == ';' and CITATION_DATE.search(tail):
            value = -0.8
        elif token in {';', ');'}:
            # A capitalized list entry, rather than a sentence about a college.
            words = re.findall(r'[A-Za-z]+', tail.rsplit('\n', 1)[-1])
            name_list = len(words) >= 4 and sum(
                w[0].isupper() for w in words
            ) >= len(words) / 2
            institution = words and words[-1] in INSTITUTIONS
            acronym = re.search(r'[A-Z][a-z]+ \([A-Z &-]{2,}$', tail)
            if name_list and (institution or acronym):
                value = -0.8
    elif re.fullmatch(r'\n? {4}\n {4}\n', token):
        value = -0.35
    elif token.strip() == '#####' and tail.rstrip().endswith(
        ('...', '…', 'answers')
    ):
        value = -0.3
    elif text == 'Title:':
        value = 1.1

    return (doc, text[-160:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 3951: a coarse token-class sketch.

Plain-terms summary: this component is tiny (about 0.3% of its site's output) and its
activation is mostly small, diffuse noise. Most of its variance is specific to individual
tokens, with no readable rule behind it. The only readable structure found is a few
coarse token classes, each with a small average activation. This program predicts those
class averages and 0 everywhere else:

- first token of a document (or of a packed row): about +0.03
- code/markup openers and separators (; [ { % // # and a doubled backslash): about +0.05
- markup closers and arrows (> < -> `` and the escaped newline \\n): about -0.06
- closing brackets (] }): about -0.02
- whitespace-only tokens: about -0.004
- a closing ; ) or .; right after an all-caps token, as in "A. V.;" or "(JWC);": about -0.05

Sizes are class averages, fit on training rows. On held-out training rows they explain
about 1% of the activation variance. Token identity, taken as a full lookup table, would
explain about 17%, but that is an arbitrary table of token ids, so it is not used here.
"""

READS = ()

DOC_START = 0.03
OPENERS = {";", " [", "{", "%", "//", "#", "\\\\", "[", "\t\n"}
MARKUP = {">", "<", " ->", "``", "\\n", ">\n", '"}}\n', ' \\"'}
CLOSERS = {"]", "}"}
ACRONYM_CLOSERS = {";", ");", ".;"}
VALUES = {"open": 0.048, "markup": -0.058, "close": -0.024, "space": -0.0045}
ACRONYM_VALUE = -0.05


def is_all_caps(text):
    text = text.strip()
    return text.isalpha() and text.isupper()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    if len(tokens) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    if token in ACRONYM_CLOSERS and is_all_caps(tokens[-2]):
        return carry, ACRONYM_VALUE
    if token in OPENERS:
        return carry, VALUES["open"]
    if token in MARKUP:
        return carry, VALUES["markup"]
    if token in CLOSERS:
        return carry, VALUES["close"]
    if token != "" and token.strip() == "":
        return carry, VALUES["space"]
    return carry, 0.0

programs.sol:
"""A negative signal for grammatical phrase links, mostly in Japanese,
Korean and Turkish. Surface forms of clause endings, postpositions and case endings
get fixed amplitudes. Recent script/function-word evidence gates ambiguous
pieces; a running word helps recognize endings split over tokens. The
Turkish locative check uses word frequency to reject accidental stem pieces.
Hungarian case endings and middle-dot runs get smaller negative values.
Unrecognized tokens get zero. All context resets at document boundaries.
This is a surface grammar heuristic, not a full morphological parser.
Weak lexical and inflection-specific responses are deliberately omitted.
"""
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

def word_groups(groups):
    return tuple((score, frozenset(words.split())) for score, words in groups)


# Grammatical inventories, with one approximate amplitude per role.
JAPANESE = word_groups((
    (-2.8, '上で 前に 場合 場合には 後に 比べ 結果'),  # circumstance
    (-1.6, 'ないと なら ば'),  # condition
    (-1.9, 'ても としても なくても なのに のに'),  # concession
    (-4.0, 'ではなく'),  # contrast
    (-1.25, 'いて おり し して しても ず って て ており'),  # continuative
    (-1.8, 'について にて にとって によって に対して に関して の中で'),  # relation
    (-1.0, 'から からは けど だから だが ですが なので ので'),  # connective
    (-2.2, 'あたり など 以外'),  # limiter
    (-0.75, 'での では でも として には にも による'),  # oblique
    (-0.4, 'が に は も'),  # particle
))
TR_WORDS = set('bir için olarak değil veya daha kadar gibi sonra'.split())
HU_WORDS = set('hogy és nem egy vagy volt mert mint kell ezt pedig'.split())
TR_POSTPOSITIONS = word_groups((
    (-4.7, 'göre ise için rağmen'),  # purpose
    (-3.2, 'altında hakkında ile içinde sonra üzerinden şeklinde'),  # relation
    (-2.0, 'gibi kadar olarak yüzden önce üzerine'),  # comparison
    (-1.5, 'ama da de ve veya'),  # conjunction
    (-1.9, 'bu şu'),  # demonstrative
))
TR_SUFFIXES = word_groups((
    (-8.0, 'arak erek'),  # gerund
    (-2.5, 'ca ce lice lıca ça çe'),  # adverbial
    (-1.5, 'ak ek'),  # infinitive
    (-1.0, 'an en'),  # participle
    (-3.0, 'ki'),  # relative
    (-3.8, 'sa se'),  # conditional
    (-6.5, 'ince ken unca ünce ınca'),  # temporal
    (-4.6, 'ada arda anda da de ede erde inde nda nde ta te unda ünde '
           'ında larda lerde larında lerinde'),  # locative
    (-2.7, 'adan dan den eden inden tan ten undan ünden ından'),  # ablative
    (-2.9, 'la le yla yle'),  # instrumental
))
KOREAN = word_groups((
    (-4.7, '경우 때 보면'),  # time
    (-5.5, '때문에 위하여 위해'),  # purpose
    (-8.5, '통해'),  # means
    (-4.0, '불구하고 않고'),  # concession
    (-4.0, '로서 으로서'),  # capacity
    (-5.0, '대해 따라 의해'),  # relation
    (-3.0, '등 위한 함께 후'),  # nominal
    (-2.0, '에는 에서 으로 이후'),  # oblique
    (-0.9, '과 로 에 와 이나'),  # particle
))
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
HANGUL = regex.compile(r'\p{Hangul}')


def group_value(text, groups):
    for score, words in groups:
        if text in words:
            return score
    return 0.0


@lru_cache(maxsize=16384)
def plausible_locative(word):
    stem = word.lower()[:-2]
    if "'" in word or '’' in word:
        return True
    frequency = zipf_frequency(stem, 'tr')
    return (len(stem) > 1 and frequency >= 2.0
            and frequency >= zipf_frequency(word.lower(), 'tr') - 1.5)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0., 0., 0., 0., '')
    _, tr, hu, ja, ko, word = carry
    previous_word = word
    s = prefix.token_strings[-1]
    t = s.strip()
    tr *= .94
    hu *= .97
    ja *= .9
    ko *= .9
    if (any(c in s for c in 'ıİğĞ') or
            tr > .05 and any(c in s for c in 'şŞ') or
            s.startswith(' ') and t in {'için', 'olarak', 'değil', 'veya', 'gibi', 'sonra'}):
        tr = 1.
    if any(c in s for c in 'őŐűŰ'):
        hu = 1.
    if s[:1].isspace() or not s.isalpha():
        if word.lower() in TR_WORDS:
            tr = 1.
        if word.lower() in HU_WORDS:
            hu = 1.
    if KANA.search(s):
        ja = 1.
    if HANGUL.search(s):
        ko = 1.
    if t in {"'", '’'} and word:
        word += t
    elif s[:1].isspace() or not s.isalpha():
        word = t if t.isalpha() else ''
    else:
        word = (word + s)[-40:]

    value = 0.0
    # Japanese clause links and the comma, distinguished from Chinese.
    if ja > .1 or KANA.search(s):
        value = group_value(t, JAPANESE)
        if t.startswith('、'):
