        if t == 'も' and previous_word.endswith(('て', 'で')):
            value = -3.0
        if t == 'と' and previous_word.endswith(tuple('うくぐすつぬぶむるい')):
            value = -2.8
        if t == 'で':
            value = -4.5 if previous_word.endswith('こと') else -2.0
        if t.endswith(('ため', 'ために')):
            value = -4.1
        if t.endswith(('ると', 'たら', 'れば')):
            value = -2.1
        if t.endswith('ながら'):
            value = -2.8
        if t in {'によって', 'により', 'ことで', 'だけで', 'などで'}:
            value = -3.8
        if t in {'とともに', 'と共に'}:
            value = -5.5
        if t in {'際', '際に'}:
            linked = previous_word.endswith(('の', 'る', 'た', 'う', 'く', 'に'))
            value = -5.5 if linked else 0.
        if t in {'時に', 'とき', '間に'}:
            value = -2.9
        if t == '時' and previous_word.endswith(('る', 'た', 'い', 'の')):
            value = -3.0
        if value == 0. and len(t) > 1 and t.endswith(('て', 'で')):
            value = -.9
    # Korean adverbial/connecting endings and relational words.
    if HANGUL.search(s):
        value = group_value(t, KOREAN)
        # Bound verb endings differ from space-prefixed word beginnings.
        if not s.startswith(' '):
            if t.endswith(('며', '면서')):
                value = -5.9
            elif t.endswith(('면', '는데')) or t == '데':
                value = -3.8
            elif t in {'하여', '해서', '므로'}:
                value = -4.8
            elif t in {'고', '서', '해', '니'}:
                value = -1.2
        if t in {'위해서', '위하여'}:
            value = -5.5
        if t.endswith('거나'):
            value = -3.5
        if t == '해' and previous_word.endswith('인'):
            value = -5.5
        if t == '써' and previous_word.endswith('로'):
            value = -8.5
        if t == '에도':
            value = -4.
        if t == '때':
            value = -5.5 if s.startswith(' ') else -3.4
        if t == '등':
            value = -4.8 if s.startswith(' ') else -2.2
    if ko > .3 and t in {'“', '"'} and s.startswith(' '):
        value = -3.8
    # Turkish suffixes and postpositions, respecting word boundaries.
    latin = bool(regex.fullmatch(r"[\p{Latin}'’]+|,", t))
