        if s.startswith(' '):
            value = group_value(t.lower(), TR_POSTPOSITIONS)
        else:
            value = group_value(t.lstrip("'’"), TR_SUFFIXES)
            if t in {'a', 'e'} and word.endswith(('rsa', 'rse')):
                value = -9.
        if not s.startswith(' '):
            if t in {'da', 'de', 'ta', 'te'}:
                value = -4.8 if plausible_locative(word) else 0.
            if t.endswith(('aki', 'eki')):
                value = -4.5
            if t.endswith(('rsa', 'rse')) and len(t) <= 3:
                value = -8.5
            if t.endswith(('ırken', 'irken', 'urken', 'ürken')):
                value = -6.5
            if t == 'en' and word.endswith(('arken', 'erken')):
                value = -6.5
            if (t in {'a', 'e'} and previous_word.endswith(('d', 't'))
                    and plausible_locative(word)):
                value = -5.5
            if word.endswith('gerek'):
                value = -2.
            if word.endswith('gereken'):
                value = 0.
            if word.lower() in {'burada', 'orada', 'şurada', 'böylece'}:
                value = -7.
        if s.startswith(' ') and t.lower() in {'ayrıca', 'sırasında', 'ki'}:
            value = -4.8
        if t == ',':
            value = -1.2
