            'ban', 'ben', 'nak', 'nek', 'val', 'vel', 'hoz', 'hez',
            'höz', 'ból', 'ből', 'ról', 'ről', 'tól', 'től',
            'ig', 'ért', 'ként', 'an', 'en', 'asan', 'esen', 'én',
