"""A local third-person-plural grammar heuristic.

Plural copulas and pronouns have positive baselines. Recent plural words
adjust verbs,
articles and singular forms; first/second-person and singular pronouns suppress
many of these responses. This is word-class logic, not a full syntactic parser.
WordNet supplies English morphology. Split words are assembled incrementally,
and the twelve-word history resets at sentence and document boundaries.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
PLURAL = {'they', 'their', 'them', 'theirs', 'themselves', 'are', 'were',
          'both', 'all', 'some', 'several', 'these', 'those', 'people'}
OTHER_PERSON = {'i', 'you', 'we', 'he', 'she', 'it'}
MODALS = {'to', 'can', 'could', 'may', 'might', 'must', 'shall',
          'should', 'will', 'would'}
PREPOSITIONS = {'to', 'from', 'in', 'on', 'by', 'as', 'into', 'with',
                'about', 'at', 'for', 'of', 'out', 'over', 'through'}
# Selected plural forms of be, have and modal verbs across European languages.
PLURAL_AUXILIARIES = {
    'sont', 'ont', 'sind', 'haben', 'werden', 'waren', 'zijn', 'hebben',
    'son', 'han', 'são', 'têm', 'sono', 'hanno', 'erano', 'están', 'eran',
    'sean', 'estaban', 'serán', 'hayan', 'sejam', 'estão', 'eram', 'tenham',
    'étaient', 'seront', 'aient', 'podem', 'pueden', 'deben', 'peuvent',
    'doivent', 'wurden',
}

@lru_cache(maxsize=50000)
def forms(word):
    nouns = wordnet.base_forms(word, 'noun')
    verbs = wordnet.base_forms(word, 'verb')
    plural = bool(nouns and any(b != word for b in nouns)
                  and (word.endswith('s') or word not in nouns))
    return plural, bool(nouns), bool(verbs), word in verbs


def plural_word(word):
    return word in PLURAL or forms(word)[0]


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        word, history = '', ()
    else:
        _, word, history = carry
    continuation = bool(word and token[:1].isalpha())
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part.isalpha():
            word += part.lower()
        else:
            if word:
                history = (*history[-11:], word)
                word = ''
            if re.search(r'[.!?;\n]', part):
                history = ()
    carry = (doc, word, history)
    if not word or not token[-1:].isalpha():
        return carry, 0.0

    p = max((0.88 ** i for i, w in enumerate(reversed(history))
             if plural_word(w)), default=0.0)
    n = max((0.75 ** i for i, w in enumerate(reversed(history[-5:]))
             if w in OTHER_PERSON), default=0.0)
    near = float(bool(history and plural_word(history[-1])))
    modal = float(bool(history and history[-1] in MODALS))
    there = float('there' in history[-3:])

    if word in {'are', 'aren'}:
        value = .97 + .24*p - .40*near - .61*n - .64*there
    elif word == 'were':
        value = .84 + .17*p - .15*near - .39*n - .19*there
    elif word == 'their':
        value = .99 + .23*p - .12*near - .05*n + .06*modal
    elif word in {'them', 'theirs', 'themselves'}:
        value = .80 + .16*p
    elif word == 'they':
        value = .75 + .12*p - .04*near - .05*n
    elif word in {'have', 'haven'}:
        value = .61 + .26*p - .55*n - .38*modal
    elif word == 'be':
        value = .17 + .38*p - .12*near - .30*n + .04*modal - .17*there
    elif word == 'been':
        value = .28 + .18*p - .26*near - .16*n - .04*there
    elif word in {'a', 'an'}:
        predicative = bool(history and history[-1] == 'as')
        value = -.23*p + .25*near - .17*modal + .21*there
        value -= .38*p*predicative
    elif word in {'is', 'was', 'has'}:
        value = .04 - .20*p + .14*n + .17*there
    elif word in {'it', 'its', 'itself'}:
        value = .05 - .16*p + .11*near + .13*n
    elif word in PLURAL_AUXILIARIES:
        # English 'son' is a noun, so require a nearby Spanish function word.
        spanish = any(w in {'el', 'los', 'las', 'del', 'y', 'es', 'sus',
                            'cuáles', 'qué', 'todos'} for w in history)
        value = 1.18 if word != 'son' or spanish else 0.0
    elif token.strip() in {'都', '都是', '均', '皆'}:
        value = .56
    elif word in {'same', 'equal', 'identical', 'alike', 'together',
                  'respective', 'respectively'}:
        value = .28 + .22*p - .08*n
    elif word in {'who', 'whom', 'qui'}:
        value = .21 + .11*p + .04*modal
    elif word in {'which', 'que', 'che', 'som', 'yang', 'которые'}:
        value = .18 + .06*near - .04*modal
    elif word == 'that':
        value = .04*p + .05*near - .05*n
    elif word in PREPOSITIONS:
        value = -.04 + .10*p - .06*n - .04*there
    elif word in {'all', 'several', 'each', 'every', 'one', 'another'}:
        value = -.08 - .09*p + .05*near
    else:
        plural, noun, verb, base = forms(word)
        if plural:
            value = -.06*p if continuation else -.10*p + .09*n
        elif base:
            value = .05*p + .04*near if noun else .04 + .18*p - .06*modal
        elif verb and not word.endswith('s'):
            value = .05*p - .07*n
        else:
            value = 0.0
    return carry, float(value)

"""Approximate short l/n/r-to-r spelling clusters, especially ler and ner.

A negative response is strongest on short er syllables, including those
split across two tokens.  Other r-vowels are weaker.  Long tokens, suffixes,
and common nasal endings attenuate the response.  Alphabetic scripts are
transliterated; Han characters are excluded rather than treated as pinyin.
These are spelling heuristics, not a complete phonetic or semantic model.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()

# Columns: e-r, i-r, other vowel-r (including bare r).
WITHIN = {
    'l': (-3.13, -0.06, -0.73),
    'n': (-2.15, -0.39, -0.16),
    'r': (-0.59, -0.03, 0.02),
}
# Same columns; pairs distinguish short (<=3 letters) and longer stems.
ACROSS = {
    'l': ((-4.57, -2.74), (-3.17, -0.23), (-1.63, -0.52)),
    'n': ((-4.00, -2.08), (-0.80, -0.19), (-0.83, -0.51)),
    'r': ((-1.98, -1.49), (-0.77, -0.13), (-0.39, -0.12)),
}
AFTER_VOWELS = (-1.99, -0.94, -0.48)


def family(vowels):
    return 0 if vowels == 'e' else 1 if vowels == 'i' else 2


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


@lru_cache(maxsize=65536)
def predict(previous, text):
    if regex.search(r'\p{Script=Han}', text):
        return 0.0
    s = spelling(text)
    if not re.fullmatch(r'\s*[a-z]+', s):
        return 0.0
    w = s.strip()
    value = 0.002 if 'r' in w and len(w) < 6 else 0.0
    if s == w and re.fullmatch(r'[aeiouy]*r[sn]?', w):
        value += 0.028
    for m in re.finditer(r'([lnr])([aeiouy]*)r', w):
        strength = 0.5 ** max(0, len(w) - 3)
        tail = w[m.end():]
        if tail:
            strength *= 0.8 if tail in ('s', 'n') else 0.5
        value += strength * WITHIN[m[1]][family(m[2])]

    m = re.match(r'^([aeiouy]*)r', w)
    p = spelling(previous).strip()
    if m and s == w and p:
        column = family(m[1])
        tail = w[m.end():]
        strength = 1.0 if not tail else 0.75 if tail in ('s', 'n') else 0.4
        strength /= max(1, len(m[1]))
        if p[-1] in ACROSS:
            amplitude = ACROSS[p[-1]][column][len(p) > 3]
            if len(p) > 6:
                strength *= 0.5
            if p.endswith(('ion', 'ian', 'ign', 'ean')):
                strength *= 0.25
            value += strength * amplitude
        elif re.search(r'[ln][aeiouy]+$', p):
            value += strength * AFTER_VOWELS[column]
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), float(predict(previous, text))

"""A spelling-and-boundary approximation, not a full contextual model.

Predict large negative responses to split 'the' spellings and archaic th'.
Short 'the'-like fragments are weaker, especially outside prepositional
contexts. Treat he by its preceding grammatical context, de after Dutch
prepositions, and die after an Afrikaans function-word cue. Separate rules
cover initial punctuation/end markers and repeated interpuncts. Most tokens
predict zero. Amplitudes are rounded training group means; many contextual
variations remain unexplained. State resets at each document boundary.
"""
import re
import unicodedata

READS = ()
PREPOSITIONS = set('of to in on at by for from with into over under through '
                   'between about before after until without among'.split())
CLAUSE_OR_JOIN = set('that which who whom where when while if because although '
                    'though whether what how why as and but or so yet then'.split())
AUXILIARIES = set('is are was were be been being has have had will would '
                  'can could should does did do'.split())
DETERMINERS = set('a an the this these those his her'.split())
DUTCH_PREPOSITIONS = set('van in op om aan met bij over tussen door naar '
                        'uit tegen onder voor'.split())
AFRIKAANS_CUES = set('vir sy hul sedert gedurende'.split())
THE_LIKE = set('teh tre rhe thr tho thu ther'.split())


def response(s, tail, previous, position, afrikaans):
    word = s.strip().lower()
    # Remove accents only for a th-initial spelling, such as Vietnamese thẻ.
    if word.startswith('th'):
        plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                        if not unicodedata.combining(c))
        word = 'teh' if plain == 'the' and word != plain else plain
    joined = tail.replace('\x00', '')
    glued = bool(s) and not s[0].isspace()

    if s == '<|endoftext|>' and position < 5:
        return -4.57 if position == 0 else -1.62
    if position == 0 and s.lstrip().startswith('.'):
        return -0.69
    if position == 0 and s.startswith('/'):
        return -0.39
    if s == '··' and tail.endswith('··'):
        return -2.23

    if glued:
        if re.search(r'\bth$', joined, re.I) and s in {"'", '’'}:
            return -5.96
        if joined.endswith("'t") and word == 'he':
            return -7.23
        if joined.endswith('ſ') and word == 'he':
            return -3.0
        if joined.lower().endswith('th') and word.startswith('e'):
            if word == 'e' and ('\x00' in tail or
                                re.search(r'\bth$', joined, re.I)):
                return -6.95
            if re.search(r'\bth$', joined):
                return -2.28
            if re.search(r'\bTh$', joined):
                return 0.37
            return -0.10
        if joined.lower().endswith('t') and word.startswith('h'):
            if re.search(r'\bt$', joined):
                return -2.45
            if re.search(r'\bT$', joined):
                return -2.65
            if word == 'he':
                if (len(joined) >= 2 and joined[-2].isalpha()
                        and joined[-2].lower() not in 'aeiou'):
                    return -3.99
                return -0.53
            return -0.15
    if word == 'e' and re.search(r'\b[Tt] h\s*$', tail):
        return -6.95

    if word == 'de':
        if previous in DUTCH_PREPOSITIONS:
            return -1.18
        return -0.45 if previous in PREPOSITIONS | AUXILIARIES else 0.0
    if word == 'die':
        return -3.01 if afrikaans else 0.09
    if word in {'he', 'th', 'te'} or word in THE_LIKE:
        if s.strip() == 'He':
            return -0.01
        if word == 'he':
            if glued and tail:
                if tail[-1].isalpha():
                    return 0.14 if tail[-1].lower() in 'aeiou' else -0.43
                if tail[-1].isspace():
                    return -0.83
            if tail[-1:].isdigit():
                return -0.75
            if tail.endswith('.'):
                return -0.55
            if tail and tail[-1] in ',;:!?"”':
                return -0.02
            if previous in PREPOSITIONS:
                return -0.56
            if previous in CLAUSE_OR_JOIN:
                return -0.02
            if previous in AUXILIARIES:
                return -0.30
            return -0.07 if previous in DETERMINERS else -0.16
        if tail[-1:].isdigit():
            return -0.17 if word == 'te' else 0.0
        if previous in PREPOSITIONS:
            return -1.0 if word == 'th' else -1.63 if word == 'te' else -1.78
        return -0.19 if word == 'th' else 0.0 if word == 'te' else -0.29
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', False, 0)
    _, raw_tail, afrikaans, position = carry
    tail = raw_tail.decode('utf-8', errors='replace')
    s = prefix.token_strings[-1]
    words = re.findall(r'[A-Za-z]+', tail)
    previous = words[-1].lower() if words else ''
    value = response(s, tail, previous, position, afrikaans)
    afrikaans = afrikaans or (s[:1].isspace() and previous in AFRIKAANS_CUES)
    raw_tail = (raw_tail + prefix.token_bytes[-1])[-192:]
    return (doc, raw_tail, afrikaans, position + 1), value

"""Detect numeric grouping, printf conversions, and split indentation.

Third digits after a numeric comma are positive (also fullwidth digits).
Decimal/list contexts weaken that response. Split runs of spaces are
negative, especially at line starts. Scale words and document starts get
small offsets; an end-of-text marker at the very start gets a large one.
Most token-specific and multilingual variation is left unmodelled.
"""
import re
import unicodedata

READS = ()
CONVERSIONS = set('diuoxXfFeEgGaAcspvTtqbwr')
SCALES = {'thousand', 'million', 'billion', 'trillion'}


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail, previous = ('', '') if first else carry[1:]
    text = ''.join(str(unicodedata.decimal(c)) if c.isdecimal()
                   else ',' if c == '，' else c for c in s)
    value = 0.0
    if s == ' ' and previous and not previous.strip(' '):
        n = len(previous)
        indent = not tail.rsplit('\n', 1)[-1].strip()
        if 2 <= n <= 4:
            value = -0.70 if indent else -0.43
        elif n > 4 or indent:
            value = -0.43
    elif len(text) == 1 and text in '0123456789':
        m = re.search(r'([0-9]+)([,\xa0])([0-9]{2})$', tail)
        if m:
            value = 0.6 if m[2] == '\xa0' else 1.35
            if m[2] == ',':
                value -= 0.27 * m[3].startswith('1')
                value -= 0.20 * (len(m[1]) > 3)
                value -= 0.65 * tail[:m.start()].endswith('.')
                value -= 0.22 * (tail.count(',') > 2)
    elif ((s in CONVERSIONS and re.search(r'%[-+ #0-9.]*$', tail))
          or (len(s) == 2 and s[0] == '%' and s[1] in CONVERSIONS)):
        value = 1.15
    elif s.strip().lower() in SCALES:
        value = 0.28
    if first:
        if s == '<|endoftext|>':
            value = -4.13
        else:
            value = -0.45 if s.isspace() else -0.05 if s.isdigit() else -0.24
    return (doc, (tail + text)[-80:], s), float(value)

"""A surface-form response to document openings.

Raw control characters, comment/markup delimiters and quotation marks can have
large opening responses. Dot-prefixed names and hash-prefixed headings tend
negative. Ordinary opening words get a small positive response. The same value
persists through an uninterrupted repetition of the opening token. Away from
these openings the approximation is almost zero, except for embedded NULs.
This does not attempt to explain the component's many small lexical variations.
"""
READS = ()


def opening(token):
    # Whitespace and encoding artifacts at the beginning of a document.
    if token == '\x00':
        return 2.81
    if token == '\r':
        return 7.10
    if token == '\n':
        return 0.21
    if token == '\n\n':
        return -0.15
    if token == '\t':
        return -0.21
    if token == '··':
        return -0.85

    # Familiar markup, code-comment and escaping conventions.
    if token == '//\n':
        return 7.85
    if token == '//':
        return 0.71
    if token == '<!':
        return 4.23
    if token == '--':
        return -1.72
    if token == '__':
        return 1.04
    if token == '"' or token == '\\"':
        return 1.0
    if token == '\\t':
        return 0.91
    if token == '<|endoftext|>':
        return 1.15
    if token.startswith('<|'):
        return 0.33
    if token.startswith('.') and any(c.isalpha() for c in token):
        return -0.47
    if token.startswith('#'):
        return -0.44

    text = token.strip()
    if not text:
        return 0.0
    if len(text) == 2 and text.isascii():
        return 0.19 if text.islower() else 0.29
    if text.lower() in {'a', 'an', 'the'}:
        return 0.23
    if text.isalpha():
        return 0.13
    if text == '1':
        return 0.33
    return 0.05


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        age, first, repeated = 0, token, True
    else:
        age, first = carry[1] + 1, carry[2]
        repeated = carry[3] and token == first

    value = -0.002
    if repeated:
        value = opening(token)
    elif token == '\x00':
        value = -0.13
    elif age == 1:
        if first == '{' and token == '[':
            value = 1.42
        elif first == '//\n' and token == '//':
            value = 0.47
        elif first == '<!' and token == 'DOCTYPE':
            value = 0.47
    return (document, age, first, repeated), value

programs.haiku:
"""Prepositions that complete a fixed phrase are pushed negative (strongly for verbs,
adjectives and nouns that select one preposition: 'distinguish between', 'participate in',
'focus on', 'difference between', 'responsible for', 'comply with'), and weakly for quantity
and result nouns ('number of', 'result in', 'range of'). A few participles ('compared to',
'educated in', 'excited about') push the following preposition slightly positive."""

READS = ()

PREPOSITIONS = {"in", "of", "for", "to", "with", "on", "from", "by", "at", "between", "about",
                "into", "over", "against", "through"}
STRONG_NEG = {
    "distinguish", "differentiate", "distinction", "difference", "differences", "relationship",
    "correlation", "participate", "participated", "participating", "participation", "invest",
    "invested", "investing", "responsible", "comply", "compliance", "compatible", "incompatible",
    "equipped", "focus", "focuses", "focusing", "focused", "interested", "worry", "worried",
    "majority", "plurality", "increase", "contribute", "contributing", "dedication", "commitment",
    "rely", "aware", "involved", "capable", "interact", "interacting",
}
WEAK_NEG = {"decrease", "resulted", "engage", "range", "result", "number", "combination"}
POSITIVE = {"compared", "educated", "excited", "challenge", "challenges", "signed", "scared"}

# typical activation of each preposition when no word above precedes it
BASELINE = {"between": -0.25, "for": 0.06, "from": 0.05, "with": 0.04, "about": -0.04, "into": -0.04}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    if cur not in PREPOSITIONS:
        return carry, 0.0
    prev = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if prev in STRONG_NEG:
        return carry, -0.6
    if prev in WEAK_NEG:
        return carry, -0.2
    if prev in POSITIVE:
        return carry, 0.3
    return carry, BASELINE.get(cur, 0.0)

programs.sol:
"""Approximate path-opening slashes and a geographic-suffix response.

Spaces, quotes, opening brackets, colons and equals signs can introduce a
root path. Division and closing-tag slashes are treated differently. There
is also a separate geographic-name signal for 州/洲 and 주.
At the start of context a coarse token-shape baseline replaces the ordinary
near-zero baseline. Common short English words get a higher initial baseline
than long, uncommon ones; much first-token variation remains unexplained.
"""
import math
from wordfreq import zipf_frequency

READS = ()


def first_token(s):
    t = s.strip()
    if t.startswith('<|'):
        return -0.20
    if '\ufffd' in t:
        return 0.72
    if not t:
        return 0.13
    if t.isdigit():
        return -0.08
    if t.isalpha() and not t.isascii():
        return -0.63
    if t.isascii() and t.isalpha():
        return -0.32 - 0.18 * math.log1p(len(t)) + 0.08 * zipf_frequency(t, 'en')
    if any(c.isalpha() for c in t):
        return -0.15
    return 0.15


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = s.strip()
    previous = prefix.token_strings[-2] if prefix.position else ''
    initial = prefix.position == 0
    if not initial:
        initial = prefix.document_ids[-1] != prefix.document_ids[-2]
    if initial or previous == '<|endoftext|>':
        return None, first_token(s)

    value = 0.0
    if t == '/':
        if s.endswith(('\n', '\r')):
            value = -0.06
        elif s[:1].isspace():
            if previous.strip().isdigit():
                value = 0.0
            elif previous.rstrip().endswith((')', ']', '}')):
                value = 0.10  # usually division, rather than a root path
            elif previous.endswith(':'):
                value = 1.87
            elif previous.strip() == 'cd':
                value = 1.42
            elif previous.strip() == 'file':
                value = 1.55
            else:
                value = 1.0
        elif previous.endswith(('"', "'", '(', '[')):
            value = 1.7
        else:
            value = 0.02
    elif t.endswith('/') and t.count('/') == 1:
        opener = t[:-1]
        if opener and all(c in ':=\"\'([{!`' for c in opener):
            if opener in (':', '='):
                value = 2.4
            elif s[:1].isspace() and opener in ('"', "'"):
                value = 2.0
            elif opener == '"':
                value = 1.2
            else:
                value = 1.65
        elif '.' in opener and all(c in '.\"\'(' for c in opener):
            value = 0.22  # relative rather than absolute paths
    elif t == '://':
        value = -0.15
    elif t == 'usr' and previous.endswith('/'):
        value = 1.5  # the conventional Unix /usr directory
    elif t == '州':  # state/prefecture; also a Chinese place-name suffix
        value = 2.4
    elif t.endswith('州'):
        value = 1.15
    elif t == '洲':  # continent/island
        value = 1.8
    elif t.endswith('洲'):
        value = 0.20
    elif t == '주':  # Korean state/province syllable
        value = 1.0
    elif t.lower() == 'zhou':
        value = 1.5
    elif t == '／':
        value = 0.30
    return None, value

programs.haiku:
"""Layer-1 MLP neuron 3961 (the down_proj component 3961), read as a weak lexical detector.

Its activation is mostly near zero (std about 0.05) and spread over many tokens with no
single theme, so this program gets only a small share of the variance. It captures the
consistent tendencies that exist, all read from the current token and the document start:

* Positive: the middle-dot characters (strongly); degree and quantity words such as
  "very", "much", "many", "less"; time words such as "year", "since", "before", "first";
  log and output file-name pieces such as ".log", ".out", ".error", "/bin", and "import".
* Negative: code and shell symbols such as "::", "#", "$$", "**", "&&", "/*", "://"; path
  words such as "/python", "/test", "/src", "package"; the words "able", "'ve", "are",
  "can", "may".
* At the start of a document (no context yet), a capitalised word leans positive and a
  lowercase or space-led token leans negative.

Everything else predicts 0. The values are scaled so they fit the measured spread.
"""

READS = ()

MIDDLE_DOT = {"··", " ·", "·"}
DEGREE_TIME = {" very", " much", " many", " less", " quite", " few", " more",
               " year", " Since", " since", " before", " first", " next", " ago"}
LOG_FILES = {".log", ".out", ".sum", ".error", ".run", ".start", ".http", "/bin",
             "/packages", "import", "\timport"}
CODE_PATH = {"::", "#", "$$", "**", "&&", "/*", "://", "/python", "/problem", "/test",
             "/src", "package"}
NEG_WORDS = {" able", "'ve", " are", " can", " may"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if token[:1].isupper():
            return None, 0.07
        if token[:1].islower() or token[:1] == " ":
            return None, -0.04
        return None, 0.0
    if token in MIDDLE_DOT:
        return None, 0.2
    if token in DEGREE_TIME:
        return None, 0.06
    if token in LOG_FILES:
        return None, 0.07
    if token in CODE_PATH or token in NEG_WORDS:
        return None, -0.05
    return None, 0.0

"""Chat-template control tokens: the component writes a strong negative value on
the special tokens that open and close chat turns and tool calls, and about zero elsewhere."""

READS = ()

TOOL_TAG_END = {"</tool_response>": -4.3, "<tool_call>": -4.0}
TOOL_TAG = {"</tool_call>": -3.2, "<tool_response>": -3.2, "<think>": -3.4, "</think>": -3.4}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok in TOOL_TAG_END:
        return carry, TOOL_TAG_END[tok]
    if tok in TOOL_TAG:
        return carry, TOOL_TAG[tok]
    if tok == "<|im_start|>":
        return carry, -0.9 if prev == "<|endoftext|>" else -3.0
    if tok == "<|im_end|>":
        return carry, -1.5 if prev in ("</tool_response>", "</tool_call>") else -2.5
    return carry, 0.0

