            value = -2.2
        elif word in {'reason', 'reasons', 'responsibility'}:
            value = -2.75
        elif word in {'credit', 'credited', 'charged', 'reward'}:
            value = -1.9
        elif word == 'up':
            value = -0.8
        elif word.startswith(('prepar', 'provid')):
