READS = ()
"""Layer-1 MLP down-projection feature 3963, as a word-level rule.

The component is mostly quiet. It turns negative on a few specific words and on the
preposition that follows a care or responsibility word, and turns positive on some
Greek word-pieces and on 'protection'/'rate'-type words. Everything else is predicted 0.
The table of values is each trigger's average activation (SCALE = 1 keeps them
as measured)."""

SCALE = 1.0

# Prepositions after care/payment verbs ("care of", "paying for"): strongly negative.
CARE_FOR = {"care", "cared", "cares", "caring", "pay", "pays", "paid", "paying"}
# Prepositions after responsibility/reason words ("responsible for", "reasons for").
RESPONSIBLE_FOR = {"responsible", "reason", "reasons", "blame", "accountable", "liable"}

# Whole words about reproduction, parenthood, repair and repayment: negative.
NEGATIVE_WORDS = {"reproductive": -3.5, "repayment": -2.7, "parenthood": -2.6,
                  "parenting": -1.7, "repro": -1.4, "repay": -1.1, "parental": -1.1,
                  "reproduction": -0.8, "repair": -0.8, "repairs": -0.8,
                  "responsibility": -0.6, "pregnant": -0.6, "rent": -0.4}

# Positive word-pieces and words.
POSITIVE_WORDS = {"ivity": 1.2, "protection": 0.7, "率": 0.8, "rate": 0.2}
GREEK_IOTA = {"ι", "ί", "Ι"}
GREEK_BEFORE = {"π", "ρ", "τ"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    raw = toks[-1]
    cur = raw.strip().lower()
    prev = toks[-2].strip().lower() if len(toks) > 1 else ""
    value = 0.0
    if cur in ("of", "for"):
        if prev in CARE_FOR:
            value = -4.0
        elif prev in RESPONSIBLE_FOR:
            value = -2.2
    elif cur == "plan" and prev == "lesson":
        value = -3.4
    elif raw in GREEK_IOTA:
        value = 3.0 if prev.strip() in GREEK_BEFORE else 0.6
    elif cur in POSITIVE_WORDS:
        value = POSITIVE_WORDS[cur]
    elif cur in NEGATIVE_WORDS:
        value = NEGATIVE_WORDS[cur]
    return None, SCALE * value

programs.sol:
"""Detect 物 ('thing/material') and its East Asian readings.

Standalone 物 responds more than fused compounds. Chemical suffixes and
words for food, creatures and luggage weaken a separately tokenized 物.
Korean 물 is strongest at a word boundary. There is a negative offset on
the first token of each document, and a negative response to doubled
middle dots. Unmatched tokens predict zero. These rules retain the large
responses rather than the many small, token-specific fluctuations.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip()
    value = 0.0
    if word == '物':
        value = 4.8
        if previous.endswith(('合', '化', '粒')):
            value = 0.7  # compounds, oxides, particulate matter
        elif previous.endswith(('食べ', '生き', '荷', '貨', '货')):
            value = 2.1  # food, living things, luggage and cargo
    elif '物' in word:
        if word == '生物':  # biology; stronger inside 抗生物質 (antibiotics)
            value = 4.6 if previous.endswith('抗') else 2.6
        elif word in {'产物', '產物'}:  # product/result
            value = 3.0
        elif len(word) == 2 and word.endswith('物'):
            value = 1.5
        elif word == '物理':
            value = 1.5
        else:
            value = 0.5
    elif word == '물':
        boundary = not previous or not previous[-1].isalpha()
        value = 6.2 if raw == word and boundary else 3.6
    elif word in {'물을', '물이', '물의', '물은', '물에', '물도'}:
        value = 4.1
    elif word == 'vật':
        value = 4.1
    elif word == 'もの':
        value = 1.15
    elif word == '것':
        value = 0.5
    elif word in {'こと', 'それ'}:
        value = 0.3
    elif word == '··':
        value = -0.72
    if first:
        value = -3.0 if word == '<|endoftext|>' else -0.4
    return (document, (previous + raw)[-4:]), value

"""Approximate a local English phrase-completion detector.

Negative spikes mark relational prepositions (parallel to, independent of),
spatial complements (north of), and relative time expressions (last year).
Positive emphatic endings include 'but not', 'whole new', and 'little bit';
the word 'straightforward' also gets a positive response.
Only adjacent tokens are used; other tokens predict zero. Fixed phrase means
are shrunk toward zero to allow for variation with the surrounding context.
"""
READS = ()
DIRECTIONS = set('''north south east west northeast northwest southeast southwest
    upstream downstream'''.split())
PERIODS = set('''week weekend month year season summer winter spring autumn fall'''.split())
COMPLEMENTS = {
    'to': set('''relevant irrelevant applicable prior close closer open new native
        endemic vital crucial critical central foreign immune adverse contrary
        dear hostile true home tangent opposite incident subservient orthogonal parallel perpendicular subject
        secondary next complementary'''.split()),
    'of': set('proud devoid excess courtesy short reminiscent'.split()),
    'with': {'consistent', 'inconsistent', 'compatible', 'familiar'},
    'in': {'rich', 'high', 'higher', 'lower', 'hidden', 'low'},
    'from': {'distinct', 'separate', 'free', 'across', 'starting'},
}
STRONG_COMPLEMENTS = {
    'to': {'subsequent', 'external', 'exclusive', 'specific', 'unique'},
    'of': set('''free independent inclusive indicative symbolic predictive
        suggestive reflective typical shy advance'''.split()),
}


def phrase_value(previous, word):
    if previous in {'north', 'south'} and word in {'east', 'west'}:
        return -2.5
    if word == 'of' and previous.lstrip('-') in DIRECTIONS:
        return -5.4
    if word in PERIODS and previous in {'last', 'next', 'this'}:
        return -0.9 if previous == 'this' else -4.4
    if previous == 'last' and word == 'night':
        return -2.7
    if word == 'in' and previous in {'early', 'earlier', 'late', 'later', 'deep'}:
        return -5.0
    if previous in STRONG_COMPLEMENTS.get(word, ()):
        return -5.2
    if previous in COMPLEMENTS.get(word, ()):
        return -2.2
    if previous == 'complete' and word == 'with':
        return -4.0
    if previous in {'just', 'right'}:
        if word in {'after', 'off', 'under', 'at'}:
            return -5.0
        if word in {'before', 'over', 'below', 'from', 'through', 'across',
                    'when', 'like'} or word in DIRECTIONS:
            return -3.0
        if word in {'in', 'as', 'away', 'last', 'then'}:
            return -1.8
    if previous in {'long', 'soon', 'shortly'} and word in {'before', 'after'}:
        return -2.8
    if previous == 'back' and word == 'in':
        return -3.0
    if previous == 'out' and word == 'there':
        return -2.0
    if previous in {'out', 'up', 'down', 'back', 'here', 'there'}:
        if word in {'in', 'on', 'at', 'to'}:
            return -0.8
    if word == 'not' and previous in {'but', 'just'}:
        return 1.6
    if previous == 'whole' and word == 'new':
        return 5.0
    if previous in {'whole', 'every'} and word in {'other', 'lot'}:
        return 1.7
    if previous == 'little' and word == 'bit':
        return 2.0
    if word == 'straightforward':
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = prefix.token_strings[-1].strip().lower()
    return (doc, word), 0.75 * phrase_value(previous, word)

"""Approximate non-sentence-ending dots: initials, abbreviations and list labels.

Initials, short capitalized words and citation abbreviations get positive
responses; ordinary word endings get little. Dots joined to a newline are
much weaker. A short document-local tail supplies the preceding word; literal
line-break escapes are treated as line breaks.
Also recognize the days 30 and 31 in dates and interpuncts following Han characters.
Web-address prefixes are excluded. Weights are rough group-level estimates;
the small lexical background and many individual abbreviation quirks are omitted.
"""
import re
import calendar
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
REFERENCES = set((
    'p pp vol no fig figs eq eqs ch chap sec art ed eds trans dept '
    'univ assoc soc inst bull proc rept etc cf viz vs v al'
).split())
LATIN_CITATIONS = set('ca cf ib ibid viz cert'.split())
MONTHS = '|'.join(calendar.month_name[1:])
DATE_END = re.compile(r'(?i)(?:\b(?:' + MONTHS + r')\s+|月)3$')
WORD = regex.compile(r'(\p{L}+|\d+)$')
DOT = re.compile(r'''[.)\],;:\-\s'"!?\\]+''')

@lru_cache(maxsize=16384)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def word_response(text):
    match = WORD.search(text)
    if not match:
        return 0.0
    word = match[0]
    before = text[:-len(word)]
    line_length = len(before.rsplit('\n', 1)[-1])
    if word.isdigit():
        number = int(word)
        if number < 2:
            return 0.0
        is_list = line_length <= 8 or before.endswith('、')
        return 0.32 if is_list and number <= 24 else 0.03
    if not regex.fullmatch(r'\p{Script=Latin}+', word):
        if len(word) == 1:
            return 0.9 if word.isupper() else (0.4 if word.islower() else 0.0)
        return 0.0
    if word.lower() == 'www' or re.search(r'https?://\S*$', text):
        return 0.0
    if word.lower() in LATIN_CITATIONS:
        return 1.2
    f = frequency(word)
    if word.istitle():
        if len(word) == 1:
            return 0.84 if f < 5.45 else 0.58
        if len(word) <= 4:
            return 1.05 if f < 4.0 else (0.69 if f < 4.9 else 0.28)
        if len(word) == 5 and f < 2.8:
            return 0.45
        return 0.0
    if word.lower() in REFERENCES:
        return 0.32 if word.isupper() else (0.89 if f < 4.8 else 0.56)
    if len(word) == 1:
        if re.search(r'(?:e\.g|i\.e)$', text, re.I):
            return 0.0
        return 0.55 if line_length <= 8 else 0.3
    if word.isupper() and len(word) <= 4:
        return 0.5 if f < 4.5 else 0.3
    if len(word) <= 6 and not re.search('[aeiouy]', word.lower()):
        return 0.5
    return 0.0


def predict(token, text, previous):
    text = text.replace(r'\n', '\n').replace(r'\r', '\n')
    if token.count('.') == 1 and DOT.fullmatch(token):
        base = word_response(text)
        if token == '.':
            return base
        if '\n' in token:
            return 0.15 * base
        return (0.6 if token.startswith('.') else 0.1) * base
    if token in {'0', '1'} and DATE_END.search(text):
        return 1.15 if token == '0' else 0.85
    if token == '·' and regex.search(r'\p{Script=Han}$', text):
        return 1.2
    if token == ' ' and text.endswith('.'):
        return -0.6 * previous
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = b'', 0.0
    else:
        _, history, previous = carry
    token = prefix.token_strings[-1]
    text = history.decode('utf-8', errors='replace')
    value = predict(token, text, previous)
    history = (history + prefix.token_bytes[-1])[-640:]
    return (doc, history, value), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:3967 -- the verb "have" (have / had / having / has).

What it does: this component fires on the verb "have" in its forms have, had,
having and has, and stays near zero on everything else. How strongly depends on
the word just before the verb:
  * bare or infinitive uses after "to", a modal (can, will, 'll, shall), "not",
    "n't", "just", "did" ("want to have", "can have", "didn't have") fire strongly;
  * modal "would/should/could/must/may/might" + have fire weakly;
  * after a subject pronoun ("I had", "you have", "they have") it is moderate;
  * after "it/that/this/there" (a third-person thing as subject) it is near zero or negative;
  * after a wh-word ("what have", "why have") it is slightly negative.
"have" after "have/has" (perfect of perfect, "has had") is very strong.
Values are the mean activation per context class, read off training text.
"""
READS = ()

STRONG = {' to', ' can', ' will', ' not', "'t", '’t', "'ll", '’ll', ' just', ' did', ' do', ' let', ' Let', ' shall'}
WEAK_MODAL = {' would', ' should', ' could', ' must', ' might', ' may'}
WH = {' what', ' why', ' where', ' how', ' nor', ' who', ' when', ' which'}
PERSON = {' I', ' you', ' we', ' You', ' We', ' they', ' They', ' he', ' He', ' she', ' She'}
THIRD = {' it', ' It', ' that', ' this', ' there', ' There', ' studies'}
PERFECT = {' have', ' has', ' had', ' Have', ' Has'}

# value per form: (after strong cue, after weak modal, after person, after third-person, after wh-word, other)
TABLE = {
    'have':   (3.5, 1.0, 0.7, 0.1, -0.3, 0.6),
    'had':    (3.5, 1.5, 1.5, -0.7, 0.2, 0.6),
    'having': (4.0, 2.5, 2.5, 2.5, 0.5, 2.4),
    'has':    (1.1, 0.5, 0.9, -0.1, -0.1, 0.15),
}
FORM = {' have': 'have', ' Have': 'have', ' had': 'had', ' Had': 'had',
        ' having': 'having', ' Having': 'having', ' has': 'has', ' Has': 'has'}


def step(carry, prefix, upstream):
    form = FORM.get(prefix.token_strings[-1])
    if form is None:
        return None, 0.0
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ''
    strong, weak, person, third, wh, other = TABLE[form]
    if prev in PERFECT and form == 'had':
        value = 7.0
    elif prev in STRONG:
        value = strong
    elif prev in WEAK_MODAL:
        value = weak
    elif prev in PERSON:
        value = person
    elif prev in THIRD:
        value = third
    elif prev in WH:
        value = wh
    else:
        value = other
    return None, value
